(window.CLAVE_TODO=window.CLAVE_TODO||{})[7]=[{"a":"Artículo 2 — Competencias ✱","q":[{"i":"7-ia-7003","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá, en los casos y en la forma que la Ley determina, del recurso y de la cuestión de inconstitucionalidad contra:","o":["Leyes y reglamentos del Estado y de las Comunidades Autónomas.","Leyes orgánicas y tratados internacionales exclusivamente.","Leyes, disposiciones normativas o actos con fuerza de Ley.","Leyes, reglamentos y actos administrativos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Leyes, disposiciones normativas o actos con fuerza de Ley</mark></span>El <span class=\"ref-norma\">art. 2.1.a de LOTC</span> dispone: <span class=\"ref-concepto\">\"Del recurso y de la cuestión de inconstitucionalidad contra Leyes, disposiciones normativas o actos con fuerza de Ley\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-141","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina:","o":["Del recurso de amparo por violación de cualesquiera derechos reconocidos en el Título I de la Constitución.","Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo 53.2 de la Constitución.","Del recurso de amparo contra las sentencias firmes dictadas por el Tribunal Supremo en cualquier orden jurisdiccional.","Del recurso de amparo por violación de los principios rectores de la política social y económica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo 53.2 de la Constitución</mark></span>El <span class=\"ref-norma\">art. 2.1.b) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo cincuenta y tres, dos, de la Constitución.\"</span>. Solo son amparables los derechos y libertades del art. 53.2 CE (arts. 14 a 29 y la objeción de conciencia del 30), no todo el Título I. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-ia-7005","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de los conflictos constitucionales de competencia:","o":["entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.","entre el Estado y las Comunidades Autónomas exclusivamente, en los términos que establezca el propio Reglamento.","entre las Comunidades Autónomas y las entidades locales.","entre los órganos constitucionales del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">entre el Estado y las Comunidades Autónomas o de los de éstas entre sí</mark></span>El <span class=\"ref-norma\">art. 2.1.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-154","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Tribunal en Pleno. El Tribunal en Pleno conoce de los conflictos:","o":["De competencia entre las Entidades locales y las Comunidades Autónomas.","En defensa de la autonomía local.","Entre las Salas del propio Tribunal Constitucional.","De jurisdicción entre el Tribunal Supremo y los Tribunales Superiores de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En defensa de la autonomía local</mark></span>El <span class=\"ref-norma\">art. 10.1.f) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"f) De los conflictos en defensa de la autonomía local.\"</span>"},{"i":"7-ia-7007","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de la declaración sobre la constitucionalidad:","o":["de los Reglamentos del Gobierno.","de los Decretos-leyes exclusivamente.","de los tratados internacionales.","de los convenios entre Comunidades Autónomas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de los tratados internacionales</mark></span>El <span class=\"ref-norma\">art. 2.1.e de LOTC</span> dispone: <span class=\"ref-concepto\">\"De la declaración sobre la constitucionalidad de los tratados internacionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7009","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar:","o":["si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.","si los mismos se han efectuado en los plazos previstos por la Constitución, conforme al procedimiento que se establezca reglamentariamente.","si los mismos respetan la composición paritaria de las Salas.","si los mismos cuentan con el respaldo de la mayoría de las Cámaras."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley</mark></span>El <span class=\"ref-norma\">art. 2.1.g de LOTC</span> dispone: <span class=\"ref-concepto\">\"De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-4","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina, entre otros, señale la incorrecta.","o":["Del recurso y de la cuestión de inconstitucionalidad contra Leyes, disposiciones normativas o actos con fuerza de Ley.","De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.","De los conflictos de defensa de la autonomía local.","De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley</mark></span>La opción D habla de Magistrados del Tribunal SUPREMO: es la falsa. Los conflictos en defensa de la autonomía local sí son de su competencia (art. 2.1.d bis). Según el <span class=\"ref-norma\">art. 2.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley\"</span> (verificado con el texto del temario)."},{"i":"7-65","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determine: señale la INCORRECTA.","o":["De la declaración sobre la constitucionalidad de los Tratados Internacionales.","De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.","De los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos.","De los conflictos en defensa de la autonomía local."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos</mark></span>El <span class=\"ref-norma\">art. 2.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"d) De los conflictos entre los órganos constitucionales del Estado. d) bis. De los conflictos en defensa de la autonomía local. e) De la declaración sobre la constitucionalidad de los tratados internacionales.\"</span>."},{"i":"7-140","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina: señale la INCORRECTA.","o":["Del recurso y de la cuestión de inconstitucionalidad contra Leyes, disposiciones normativas o actos con fuerza de Ley.","De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de uno de los éstos entre sí.","De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar a sí mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.","De los conflictos entre los órganos constitucionales del Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar a sí mismos reúnen los requisitos requeridos por la Constitución y la presente Ley</mark></span>El <span class=\"ref-norma\">art. 2.1.g) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"g) De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.\"</span>."},{"i":"7-85","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué órgano, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado?","o":["El Gobierno.","El Consejo General del Poder Judicial.","El Tribunal en Pleno.","Las Cortes Generales, a través de la comisión mixta Congreso - Senado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Tribunal en Pleno</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>. Es el Pleno quien elabora el presupuesto; el Presidente no lo aprueba."},{"i":"7-96","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. su organización y atribuciones. ¿Quién se encarga de convocar las Salas?","o":["El Presidente del Tribunal Constitucional.","El Presidente respectivo de cada Sala.","El Vicepresidente.","El Secretario del Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Presidente del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 27.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Son susceptibles de declaración de inconstitucionalidad: a) Los Estatutos de Autonomía y las demás Leyes orgánicas. b) Las demás Leyes, disposiciones normativas y actos del Estado con fuerza de Ley.\"</span>."},{"i":"7-47","p":"Ley Orgánica del Tribunal Constitucional. ¿Es necesaria la publicación de los reglamentos que dicte el Tribunal Constitucional sobre su propio funcionamiento y organización?","o":["No, al ser un documento interno no precisa de publicación.","Sí, debe ser publicado en el Boletín Oficial del Estado.","No, aunque si que podrá causar su publicación a efectos de derechos de terceros.","Sí, en el Boletín Oficial del Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sí, debe ser publicado en el Boletín Oficial del Estado</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se publicarán en el «Boletín Oficial del Estado», autorizados por su Presidente.\"</span>."},{"i":"7-74","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional podrá dictar reglamentos sobre su propio funcionamiento y organización. Estos reglamentos:","o":["Deberán ser aprobados por el Pleno del Congreso de los Diputados.","Se publicarán en el «Boletín Oficial del Estado».","Deberán ser autorizados por los Presidentes del Congreso y del Senado.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se publicarán en el «Boletín Oficial del Estado»</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se publicarán en el «Boletín Oficial del Estado», autorizados por su Presidente.\"</span>."},{"i":"7-ia-7010","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional podrá dictar reglamentos sobre su propio funcionamiento y organización, así como sobre el régimen de su personal y servicios. Estos reglamentos deberán ser:","o":["aprobados por el Tribunal en Pleno y publicados con la autorización del Gobierno, sin perjuicio de lo dispuesto en el Derecho nacional.","aprobados por las Salas y publicados en el «Boletín Oficial del Estado».","propuestos por el Presidente y aprobados por el Congreso de los Diputados.","aprobados por el Tribunal en Pleno y publicados en el «Boletín Oficial del Estado», autorizados por su Presidente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">aprobados por el Tribunal en Pleno y publicados en el «Boletín Oficial del Estado», autorizados por su Presidente</mark></span>El <span class=\"ref-norma\">art. 2.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-40","p":"Ley Orgánica del Tribunal Constitucional. En relación con el Tribunal Constitucional: Señale la opción incorrecta.","o":["Podrá dictar reglamentos sobre su propio funcionamiento y organización, que podrán ser aprobados por cualquiera de las Salas del Tribunal.","El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","Cuando el Tribunal Constitucional anule un acto o resolución que contravenga la Jurisdicción lo ha de hacer motivadamente y previa audiencia al Ministerio Fiscal y al órgano autor del acto o resolución.","El Tribunal en Pleno elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Podrá dictar reglamentos sobre su propio funcionamiento y organización, que podrán ser aprobados por cualquiera de las Salas del Tribunal</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se publicarán en el «Boletín Oficial del Estado», autorizados por su Presidente.\"</span>. Los reglamentos los aprueba el Pleno, no «cualquiera de las Salas»."},{"i":"7-ia-7006","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conoce de los conflictos en defensa de la autonomía local, que se enuncian en la Ley como:","o":["una modalidad de conflicto constitucional de competencia entre Comunidades Autónomas.","una modalidad del recurso de amparo.","una competencia del Pleno excluida de las Salas.","una atribución propia, distinta de los conflictos entre órganos constitucionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una atribución propia, distinta de los conflictos entre órganos constitucionales</mark></span>El <span class=\"ref-norma\">art. 2.1.d bis de LOTC</span> dispone: <span class=\"ref-concepto\">\"d) bis. De los conflictos en defensa de la autonomía local\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — Cuestiones prejudiciales e incidentales","q":[{"i":"7-135","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La competencia del Tribunal Constitucional se extiende:","o":["Al conocimiento y decisión de las cuestiones prejudiciales o incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta.","Al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta.","Al conocimiento y decisión de las cuestiones no prejudiciales o incidentales pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento inconstitucional de ésta.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta</mark></span>El <span class=\"ref-norma\">art. 3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta.\"</span>. La conjunción literal es «prejudiciales e incidentales» (no «o»)."},{"i":"7-ia-7011","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestiones prejudiciales e incidentales. La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce:","o":["con carácter vinculante para los órganos de la jurisdicción ordinaria.","cuando lo solicite el Ministerio Fiscal.","a los solos efectos del enjuiciamiento constitucional de ésta.","siempre que no exista pronunciamiento del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a los solos efectos del enjuiciamiento constitucional de ésta</mark></span>El <span class=\"ref-norma\">art. 3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a los solos efectos del\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5 — Composición R2","q":[{"i":"7-11","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional está integrado por _______ con el título de Magistrados del Tribunal Constitucional.","o":["Ocho miembros.","Diez miembros.","Doce miembros.","Catorce miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Doce miembros</mark></span>El <span class=\"ref-norma\">art. 5 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional está integrado por doce miembros, con el título de Magistrados del Tribunal Constitucional.\"</span>."}]},{"a":"Artículo 6 — Pleno, Sala y Sección ✱ R3","q":[{"i":"7-98","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿A quién darán cuenta las Secciones sobre las propuestas de admisión o inadmisión de los asuntos de su competencia?","o":["A la Sala Primera.","A las Salas.","Al Pleno.","A la Sala Segunda."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Pleno</mark></span>Según el <span class=\"ref-norma\">art. 8.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Se dará cuenta al Pleno de las propuestas de admisión o inadmisión de asuntos de su competencia\"</span> (verificado con el texto del temario)."},{"i":"7-30","p":"Ley Orgánica del Tribunal Constitucional. En cuanto a los recursos de amparo, indique cuál de los siguientes tiene capacidad para adoptar medidas cautelares y resoluciones provisionales:","o":["La Sala.","El Ministerio Fiscal y la Sección.","El Ministerio Fiscal y la Sala o la Sección.","La Sala o la Sección."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala o la Sección</mark></span>El <span class=\"ref-norma\">art. 56.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala o la Sección podrá adoptar cualesquiera medidas cautelares y resoluciones provisionales previstas en el ordenamiento, que, por su naturaleza, puedan aplicarse en el proceso de amparo y tiendan a evitar que el recurso pierda su finalidad.\"</span>."},{"i":"7-70","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De su organización y atribuciones. El Tribunal Constitucional actúa en: señale la INCORRECTA.","o":["Gran Sala.","Sección.","Pleno.","Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Gran Sala</mark></span>El <span class=\"ref-norma\">art. 6.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección.\"</span>."},{"i":"7-106","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional actúa en: señale la INCORRECTA.","o":["Pleno.","Gran Sala.","Sala.","Sección."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Gran Sala</mark></span>El <span class=\"ref-norma\">art. 6.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección.\"</span>."},{"i":"7-117","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional actúa en: señale la INCORRECTA.","o":["Gran Sala.","Sección.","Pleno.","Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Gran Sala</mark></span>No existe la «Gran Sala». Según el <span class=\"ref-norma\">art. 6.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7017","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Organización. El Tribunal Constitucional actúa:","o":["en Pleno, en Sala o en Sección.","en Pleno o en Sala exclusivamente.","en Pleno, en Comisión o en Sección.","en Sala o en Sección exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en Pleno, en Sala o en Sección</mark></span>El <span class=\"ref-norma\">art. 6.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7018","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Organización. El Pleno está integrado por todos los Magistrados del Tribunal. Lo preside el Presidente y, en su defecto:","o":["el Magistrado de mayor edad, y a falta de este, el más antiguo.","el Vicepresidente y, a falta de ambos, el Magistrado de menor edad.","el Presidente de la Sala Primera y, a falta de este, el de la Sala Segunda, en los términos que establezca el propio Reglamento.","el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad</mark></span>El <span class=\"ref-norma\">art. 6.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Lo preside el Presidente del Tribunal y, en su defecto, el Vicepresidente y, a falta de ambos, el Magistrado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-45","p":"Ley Orgánica del Tribunal Constitucional. ¿Quién preside el Pleno del Tribunal Constitucional en ausencia del Presidente y el Vicepresidente, cuando todos hubiesen sido nombrados al mismo tiempo en el cargo y tuvieren la misma antigüedad?","o":["El magistrado que antes hubiera iniciado la carrera judicial.","El magistrado que designe el Presidente, o en su defecto el Vicepresidente.","El magistrado de mayor edad.","El magistrado que designe el Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El magistrado de mayor edad</mark></span>El <span class=\"ref-norma\">art. 6.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Lo preside el Presidente del Tribunal y, en su defecto, el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad.\"</span>."},{"i":"7-99","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Quién preside el Pleno del Tribunal Constitucional en ausencia del Presidente y el Vicepresidente, cuando todos hubiesen sido nombrados al mismo tiempo en el cargo y tuvieren la misma antigüedad?","o":["El magistrado que antes hubiera iniciado la carrera judicial.","El magistrado que designe el Presidente, o en su defecto el Vicepresidente.","El magistrado de mayor edad.","El magistrado que designe el Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El magistrado de mayor edad</mark></span>Según el <span class=\"ref-norma\">art. 6.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Lo preside el Presidente del Tribunal y, en su defecto, el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7020","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas. El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto:","o":["el Vicepresidente del Tribunal.","el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","el Magistrado de mayor edad, en todo caso, salvo que el Estado miembro afectado disponga otra cosa.","el Magistrado de menor edad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad</mark></span>El <span class=\"ref-norma\">art. 7.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Las Salas ✱","q":[{"i":"7-23","p":"Ley Orgánica del Tribunal Constitucional. El Tribunal Constitucional consta de:","o":["Dos salas.","Tres salas.","Cuatro salas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-60","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Por cuántas salas está compuesto el Tribunal Constitucional?","o":["Tres Salas.","Cuatro Salas.","Dos Salas.","Una única Sala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos Salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-69","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional consta de Dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.","o":["Dos Salas.","Tres Salas.","Cuatro Salas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos Salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-115","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional consta de _______ cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.","o":["Dos Salas.","Tres Salas.","Cuatro Salas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos Salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-ia-7327","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la captación, reproducción o publicación por fotografía, filme o cualquier otro procedimiento, de la imagen de una persona en lugares o momentos de su vida privada o fuera de ellos, salvo los casos previstos:","o":["en el artículo segundo, dos.","en el artículo noveno, dos.","en el artículo octavo, dos.","en el artículo octavo, uno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en el artículo octavo, dos</mark></span>El <span class=\"ref-norma\">art. 7.5 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"salvo los casos previstos en el artículo octavo, dos\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-111","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. Señale la CORRECTA.","o":["El Tribunal Constitucional consta de tres Salas. Cada Sala está compuesta por siete Magistrados nombrados por el Tribunal en Pleno.","El Presidente del Tribunal lo es también de la Sala Primera, que presidirá, en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","El Vicepresidente del Tribunal presidirá en la Sala Segunda y, en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","B y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">B y C son correctas</mark></span>El <span class=\"ref-norma\">art. 7 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno. Dos. El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad. Tres. El Vicepresidente del Tribunal presidirá en la Sala Segunda y, en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.\"</span>."},{"i":"7-ia-7019","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas. El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados:","o":["nombrados por el Presidente del Tribunal.","nombrados por el Rey, a propuesta del Pleno.","nombrados por el Tribunal en Pleno.","elegidos por las Cortes Generales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">nombrados por el Tribunal en Pleno</mark></span>El <span class=\"ref-norma\">art. 7.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-26","p":"Ley Orgánica del Tribunal Constitucional. ¿Qué Salas presidirá el Presidente del Tribunal Constitucional?","o":["La Sala Primera.","La Sala Segunda.","La Sala Primera o la Sala Segunda.","La Sala Primera y la Sala Segunda."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala Primera</mark></span>La Sala Segunda la preside el Vicepresidente (art. 7.3). Según el <span class=\"ref-norma\">art. 7.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Presidente del Tribunal lo es también de la Sala Primera\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7021","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas. El Vicepresidente del Tribunal presidirá:","o":["la Sala Segunda.","la Sala Primera.","las Secciones del Pleno.","el Pleno en todo caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Sala Segunda</mark></span>El <span class=\"ref-norma\">art. 7.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El Vicepresidente del Tribunal presidirá en la Sala Segunda\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 12 — Reparto de asuntos entre las Salas R4","q":[{"i":"7-75","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La distribución de asuntos entre las Salas del Tribunal se efectuará:","o":["Según un turno establecido por la Comisión.","A propuesta del Pleno.","Según un turno establecido por el Pleno a propuesta de su Presidente.","Según un turno establecido por el Presidente a propuesta del Pleno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Según un turno establecido por el Pleno a propuesta de su Presidente</mark></span>El <span class=\"ref-norma\">art. 12 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La distribución de asuntos entre las Salas del Tribunal se efectuará según un turno establecido por el Pleno a propuesta de su Presidente.\"</span>."}]},{"a":"Artículo 13 — Cambio de doctrina","q":[{"i":"7-59","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Cuando una Sala considere necesario apartarse en cualquier punto de la doctrina constitucional precedente sentada por el Tribunal: Señale la opción correcta.","o":["La cuestión se someterá a la decisión del Consejo General del Poder Judicial.","La cuestión se someterá a la decisión del Pleno.","La cuestión se someterá a la decisión de la Sala Primera.","La cuestión se someterá a la decisión del Consejo de Gobierno."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La cuestión se someterá a la decisión del Pleno</mark></span>El <span class=\"ref-norma\">art. 13 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Cuando una Sala considere necesario apartarse en cualquier punto de la doctrina constitucional precedente sentada por el Tribunal, la cuestión se someterá a la decisión del Pleno.\"</span>."},{"i":"7-ia-7036","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Doctrina constitucional. Cuando una Sala considere necesario apartarse en cualquier punto de la doctrina constitucional precedente sentada por el Tribunal, la cuestión se someterá:","o":["a la decisión de la otra Sala.","a la decisión del Pleno.","al informe del Presidente.","a la decisión de las Cámaras."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la decisión del Pleno</mark></span>El <span class=\"ref-norma\">art. 13 de LOTC</span> dispone: <span class=\"ref-concepto\">\"la cuestión se someterá a la decisión del Pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-81","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas del Tribunal Constitucional conocerán:","o":["De los asuntos que, atribuidos a la justicia constitucional, no sean de la competencia del Pleno.","De aquellas cuestiones que, habiendo sido atribuidas al conocimiento de las Secciones, quisiesen resolver la propia Sala.","De aquellas cuestiones necesarias para apartarse a cualquier punto de la doctrina constitucional precedente sentada por el Tribunal.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 11 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las Salas del Tribunal Constitucional conocerán de los asuntos que, atribuidos a la justicia constitucional, no sean de la competencia del Pleno. Dos. También conocerán las Salas de aquellas cuestiones que, habiendo sido atribuidas al conocimiento de las Secciones, entiendan que por su importancia deba resolver la propia Sala.\"</span>. La opción C es falsa: apartarse de la doctrina constitucional precedente se somete al Pleno (art. 13), no lo resuelve la Sala."}]},{"a":"Artículo 15 — El Presidente del Tribunal","q":[{"i":"7-18","p":"Ley Orgánica del Tribunal Constitucional. Indique cuál de las siguientes funciones NO se atribuye al Presidente del Tribunal Constitucional:","o":["Preside las Salas.","Comunica al Consejo General del Poder Judicial las vacantes.","Nombra a los letrados.","Ejerce las potestades administrativas sobre el personal del Tribunal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Preside las Salas</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.\"</span>. El Presidente solo preside la Sala Primera; la Segunda la preside el Vicepresidente (art. 7)."},{"i":"7-80","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente del Tribunal Constitucional: señale la INCORRECTA.","o":["Tiene la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas.","Adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones.","Nombra los secretarios de las Salas del Tribunal.","Nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral y ejercerá las potestades administrativas sobre el personal del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Nombra los secretarios de las Salas del Tribunal</mark></span>El <span class=\"ref-norma\">art. 15 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas; adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones; comunica a las Cámaras, al Gobierno o al Consejo General del Poder Judicial, en cada caso, las vacantes; nombra a los letrados, convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral, y ejerce las potestades administrativas sobre el personal del Tribunal.\"</span>. El art. 15 no atribuye al Presidente nombrar «secretarios de las Salas»: nombra a los letrados."},{"i":"7-91","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Cuál de las siguientes funciones se atribuyen al Presidente del Tribunal Constitucional?","o":["Preside el Tribunal en Pleno.","Adopta medidas precisas para el funcionamiento de las Salas.","Comunica al Gobierno las vacantes.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 15 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas; adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones; comunica a las Cámaras, al Gobierno o al Consejo General del Poder Judicial, en cada caso, las vacantes; nombra a los letrados, convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral, y ejerce las potestades administrativas sobre el personal del Tribunal.\"</span>. Todas las funciones indicadas figuran en el art. 15."},{"i":"7-139","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente del Tribunal Constitucional: señale la INCORRECTA.","o":["Tiene la representación del Tribunal, convoca y preside el Pleno y convoca las Salas.","Adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones.","Autoriza con su firma los acuerdos del Tribunal en Pleno y de las Salas.","Nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral y ejercerá las potestades administrativas sobre el personal del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Autoriza con su firma los acuerdos del Tribunal en Pleno y de las Salas</mark></span>Autorizar con su firma los acuerdos no figura entre las funciones del art. 15. Según el <span class=\"ref-norma\">art. 15 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Presidente [...] nombra a los letrados, convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral, y ejerce las potestades administrativas sobre el personal del Tribunal\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7038","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente del Tribunal. El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Pleno y convoca las Salas, y entre otras funciones:","o":["nombra a los Magistrados de cada Sala.","propone a los Magistrados al Rey.","convoca las Secciones y decide sobre su composición, conforme al procedimiento que se establezca reglamentariamente.","nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios</mark></span>El <span class=\"ref-norma\">art. 15 de LOTC</span> dispone: <span class=\"ref-concepto\">\"nombra a los\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 42 — Actos sin valor de Ley de las Cortes y Asambleas","q":[{"i":"7-52","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Qué se requiere para proceder en vía de amparo constitucional contras las decisiones y actos sin valor de ley de las Cortes Generales que violen derecho y libertades susceptibles de amparo?","o":["Haber agotado la vía judicial procedente.","No haber transcurrido veinte días desde que sean firmes.","No haber transcurrido tres meses desde que sean firmes.","A y C son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No haber transcurrido tres meses desde que sean firmes</mark></span>Agotar la vía judicial es exigencia del art. 43 (Gobierno y autoridades), no del art. 42. Veinte días es el plazo del art. 43.2. Según el <span class=\"ref-norma\">art. 42 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las decisiones o actos sin valor de Ley, emanados de las Cortes o de cualquiera de sus órganos [...] podrán ser recurridos dentro del plazo de tres meses desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean firmes\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7162","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a decisiones de las Cortes y Asambleas. Las decisiones o actos sin valor de Ley, emanados de las Cortes o de las Asambleas legislativas de las Comunidades Autónomas, que violen los derechos susceptibles de amparo, podrán ser recurridos dentro del plazo de:","o":["veinte días desde su notificación, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","tres meses desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean firmes.","treinta días desde su publicación.","un mes desde que sean firmes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres meses desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean firmes</mark></span>El <span class=\"ref-norma\">art. 42 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán ser recurridos dentro del plazo de tres meses desde que, con arreglo a las normas internas de las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 44 · AMPARO FRENTE A ÓRGANOS JUDICIALES","q":[{"i":"7-8","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo Constitucional. De la Procedencia e Interposición del recurso de amparo Constitucional. Contra las violaciones de los derechos y libertades susceptibles de amparo Constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un Órgano Judicial, podrá interponerse recurso de amparo en el plazo de:","o":["20 días, a partir de la notificación de la resolución recaída en el proceso judicial.","20 días, a partir de la fecha de la resolución recaída en el proceso judicial.","30 días, a partir de la notificación de la resolución recaída en el proceso judicial.","15 días, a partir de la fecha de la resolución recaída en el proceso judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">30 días, a partir de la notificación de la resolución recaída en el proceso judicial</mark></span>El <span class=\"ref-norma\">art. 44.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo será de 30 días, a partir de la notificación de la resolución recaída en el proceso judicial.\"</span>."},{"i":"7-76","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial, podrán dar lugar a este recurso siempre que se cumplan los requisitos siguientes:","o":["Que se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial.","Que la violación del derecho o la libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquélla se produjo, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional.","Que se haya denunciado formalmente en el proceso, en el acto u oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>El <span class=\"ref-norma\">art. 44.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquellas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional. c) Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.\"</span>. El requisito dice que el TC no entrará a conocer de los hechos «en ningún caso»."},{"i":"7-129","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial, podrán dar lugar a este recurso siempre que se cumplan los requisitos siguientes:","o":["Que se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto, dentro de la vía judicial.","Que la violación del derecho o la libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquéllas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional.","Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiere lugar para ello.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>El <span class=\"ref-norma\">art. 44.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquellas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional. c) Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.\"</span>."},{"i":"7-ia-7166","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. Las violaciones de derechos que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial podrán dar lugar al recurso siempre que se cumplan, entre otros, el requisito de que:","o":["se haya solicitado la nulidad de actuaciones ante el Tribunal Supremo en todo caso, salvo que el Estado miembro afectado disponga otra cosa.","se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial.","se haya recabado informe del Ministerio Fiscal.","se haya interpuesto recurso ante el Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial</mark></span>El <span class=\"ref-norma\">art. 44.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Que se hayan agotado todos los medios de impugnación previstos por las normas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7167","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. La violación del derecho o libertad debe ser imputable de modo inmediato y directo a una acción u omisión del órgano judicial, con independencia de los hechos que dieron lugar al proceso, acerca de los que:","o":["en ningún caso entrará a conocer el Tribunal Constitucional.","solo entrará a conocer el Tribunal Constitucional cuando afecten a derechos fundamentales.","entrará a conocer el Tribunal Constitucional en trámite de admisión.","entrará a conocer el Pleno cuando lo solicite el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en ningún caso entrará a conocer el Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 44.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7168","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. Entre los requisitos del amparo frente a órganos judiciales figura que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional:","o":["en el escrito de interposición del recurso de apelación, conforme al procedimiento que se establezca reglamentariamente.","en el plazo de cinco días desde su conocimiento.","ante el Ministerio Fiscal.","tan pronto como, una vez conocida, hubiera lugar para ello."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tan pronto como, una vez conocida, hubiera lugar para ello</mark></span>El <span class=\"ref-norma\">art. 44.1.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"tan pronto como, una vez conocida, hubiera lugar\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7169","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. El plazo para interponer el recurso de amparo frente a actos u omisiones de órganos judiciales será de:","o":["20 días, a partir de la notificación de la resolución recaída en el proceso judicial, sin perjuicio de lo dispuesto en el Derecho nacional.","tres meses, a partir de la notificación de la resolución judicial.","30 días, a partir de la notificación de la resolución recaída en el proceso judicial.","15 días, a partir de la notificación de la resolución judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">30 días, a partir de la notificación de la resolución recaída en el proceso judicial</mark></span>El <span class=\"ref-norma\">art. 44.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo será de 30 días, a partir de la\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7202","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. Señale la INCORRECTA sobre el amparo frente a actos u omisiones de órganos judiciales:","o":["El plazo para interponerlo es de treinta días desde la notificación de la resolución judicial.","El plazo para interponerlo es de veinte días.","Hay que haber agotado todos los medios de impugnación de la vía judicial.","El Tribunal Constitucional nunca entra a conocer de los hechos del proceso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El plazo para interponerlo es de veinte días</mark></span>El <span class=\"ref-norma\">art. 44 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo será de 30 días, a partir de la\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 46.1 · ESTÁN LEGITIMADOS PARA INTERPONER EL RECURSO DE AMPARO CONSTITUCIONAL","q":[{"i":"7-147","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. En los casos de decisiones o actos sin valor de Ley emanados de las Cortes o de las Asambleas legislativas de las Comunidades Autónomas, están legitimados para interponer el recurso de amparo constitucional:","o":["La persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal.","Quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal.","La persona directamente afectada y el Ministerio Fiscal.","Cincuenta Diputados o cincuenta Senadores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 46.1.a) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"a) En los casos de los artículos cuarenta y dos y cuarenta y cinco, la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-ia-7170","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación en el amparo. En los casos de amparo frente a decisiones de las Cortes o Asambleas, están legitimados para interponer el recurso:","o":["quienes hayan sido parte en el proceso judicial, el Defensor del Pueblo y el Ministerio Fiscal.","la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal.","el Presidente del Gobierno y cincuenta Diputados.","la persona directamente afectada y el Abogado del Estado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 46.1.a de LOTC</span> dispone: <span class=\"ref-concepto\">\"la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7171","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación en el amparo. En los casos de amparo frente a actos del Gobierno o de órganos judiciales, están legitimados:","o":["quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal.","la persona directamente afectada y el Ministerio Fiscal exclusivamente, en los términos que establezca el propio Reglamento.","cualquier ciudadano con interés legítimo.","las asociaciones de consumidores y usuarios."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 46.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7172","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación en el amparo. Si el recurso de amparo se promueve por el Defensor del Pueblo o el Ministerio Fiscal, la Sala competente lo comunicará a los posibles agraviados conocidos y ordenará anunciar la interposición del recurso en el «Boletín Oficial del Estado». Dicha publicación:","o":["se realizará en el plazo de quince días.","tendrá carácter reservado.","sustituirá la notificación a los agraviados.","tendrá carácter preferente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tendrá carácter preferente</mark></span>El <span class=\"ref-norma\">art. 46.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Dicha publicación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 46 — Legitimación para el amparo ✱","q":[{"i":"7-54","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Admitida la demanda de amparo, una vez se reciban los requerimientos oportunos y haya transcurrido el tiempo de emplazamiento, la Sala dará vista de las mismas a: Señale la opción incorrecta.","o":["El Abogado del Estado.","La Administración Pública, si estuviera interesada.","El Defensor del Pueblo.","El Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Defensor del Pueblo</mark></span>El <span class=\"ref-norma\">art. 52.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala dará vista de las mismas a quien promovió el amparo, a los personados en el proceso, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal. La vista será por plazo común que no podrá exceder de veinte días, y durante él podrán presentarse las alegaciones procedentes.\"</span>."},{"i":"7-126","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Quién intervendrá en todos los procesos de amparo, en defensa de la legalidad de los derechos de los ciudadanos y del interés público tutelado por la Ley?","o":["El Ministerio Fiscal.","El Fiscal General del Estado.","El Defensor del Pueblo.","El Ministerio de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 47.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Ministerio Fiscal intervendrá en todos los procesos de amparo, en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la Ley.\"</span>."},{"i":"7-31","p":"Ley Orgánica del Tribunal Constitucional. Están legitimados para interponer el recurso de amparo constitucional por las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial. Señale la respuesta incorrecta.","o":["El Ministerio Fiscal.","El Consejo de Ministros.","El Defensor del Pueblo.","Quienes hayan sido parte en el proceso judicial correspondiente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo de Ministros</mark></span>El <span class=\"ref-norma\">art. 46.1.b) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"En los casos de los artículos cuarenta y tres y cuarenta y cuatro, quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal.\"</span>."}]},{"a":"Artículo 48 — Órganos competentes R6","q":[{"i":"7-67","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El conocimiento de los recursos de amparo constitucional corresponde a:","o":["Las Salas del Tribunal Constitucional y, en su caso, a las Secciones.","El Pleno, entre otros.","Las Salas del Tribunal Constitucional, exclusivamente.","Las respuestas A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Salas del Tribunal Constitucional y, en su caso, a las Secciones</mark></span>No es «exclusivamente» de las Salas: también las Secciones, en su caso. Según el <span class=\"ref-norma\">art. 48 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El conocimiento de los recursos de amparo constitucional corresponde a las Salas del Tribunal Constitucional y, en su caso, a las Secciones\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7186","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Vista en el amparo. Presentadas las alegaciones, la Sala podrá deferir la resolución del recurso, cuando para su resolución sea aplicable doctrina consolidada del Tribunal Constitucional:","o":["al Pleno.","a una de sus Secciones.","a la otra Sala.","al Presidente del Tribunal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a una de sus Secciones</mark></span>El <span class=\"ref-norma\">art. 52.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"cuando para su resolución sea aplicable doctrina consolidada del Tribunal Constitucional, a una de sus Secciones\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 49 — La demanda","q":[{"i":"7-38","p":"Ley Orgánica del Tribunal Constitucional. El recurso de amparo se iniciará mediante: Señale la opción correcta.","o":["Demanda.","Demanda o querella.","Tesis.","Demanda, querella o de oficio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Demanda</mark></span>No existe querella ni inicio de oficio. Según el <span class=\"ref-norma\">art. 49.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten\"</span> (verificado con el texto del temario)."},{"i":"7-73","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo. El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado.","o":["Sentencia.","Querella.","Demanda.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Demanda</mark></span>El <span class=\"ref-norma\">art. 49.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado. En todo caso, la demanda justificará la especial trascendencia constitucional del recurso.\"</span>."},{"i":"7-125","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos amparo Constitucional. El recurso de amparo constitucional se iniciará mediante _______ en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considera vulnerado.","o":["Sentencia.","Querella.","Demanda.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Demanda</mark></span>El <span class=\"ref-norma\">art. 49.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado. En todo caso, la demanda justificará la especial trascendencia constitucional del recurso.\"</span>."},{"i":"7-29","p":"Ley Orgánica del Tribunal Constitucional. ¿Cuál es un requisito en todo caso para la admisión de un recurso de amparo constitucional?","o":["La especial relevancia para la jurisprudencia.","La especial trascendencia constitucional del recurso.","La especial necesidad de cumplir lo preceptuado en la Constitución.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La especial trascendencia constitucional del recurso</mark></span>El <span class=\"ref-norma\">art. 49.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado. En todo caso, la demanda justificará la especial trascendencia constitucional del recurso.\"</span>."},{"i":"7-ia-7176","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Demanda de amparo. La demanda de amparo justificará, en todo caso:","o":["la urgencia excepcional del recurso.","el agotamiento de la vía administrativa, salvo que el Estado miembro afectado disponga otra cosa.","la cuantía del perjuicio sufrido.","la especial trascendencia constitucional del recurso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la especial trascendencia constitucional del recurso</mark></span>El <span class=\"ref-norma\">art. 49.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En todo caso, la demanda justificará la especial trascendencia constitucional del recurso\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7177","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Demanda de amparo. Con la demanda de amparo se acompañarán el documento que acredite la representación del solicitante y:","o":["el informe del Ministerio Fiscal.","el dictamen del Defensor del Pueblo.","en su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.","la acreditación del pago de las tasas, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo</mark></span>El <span class=\"ref-norma\">art. 49.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En su caso, la copia, traslado o certificación de la resolución recaída en el\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-68","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo Constitucional. Con la demanda se acompañarán:","o":["El documento que acredite la representación del solicitante del amparo.","En su caso, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.","Tanta copias literales de la misma y de los documentos presentados como partes en el previo proceso, si la hubiere, y una más para el Ministerio Fiscal.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 49.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Con la demanda se acompañarán: a) El documento que acredite la representación del solicitante del amparo. b) En su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.\"</span>."},{"i":"7-113","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo Constitucional. Con la demanda se acompañarán:","o":["El documento que acredita la representación del solicitante del amparo.","En su caso, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.","Tanto copias literales de la misma y de los documentos presentados como partes en el previo proceso, si la hubiere, y una más para el Ministerio Fiscal.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 49.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Con la demanda se acompañarán: a) El documento que acredite la representación del solicitante del amparo. b) En su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.\"</span>."},{"i":"7-ia-7178","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Demanda de amparo. De incumplirse los requisitos de la demanda de amparo, las Secretarías de Justicia lo pondrán de manifiesto al interesado en el plazo de:","o":["5 días, con el apercibimiento de que se archivará el recurso.","10 días, con el apercibimiento de que, de no subsanarse el defecto, se acordará la inadmisión del recurso.","15 días, con el apercibimiento de que se acordará la inadmisión, en los términos que establezca el propio Reglamento.","3 días, con el apercibimiento de que se tendrá por desistido."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">10 días, con el apercibimiento de que, de no subsanarse el defecto, se acordará la inadmisión del recurso</mark></span>El <span class=\"ref-norma\">art. 49.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las Secretarías de Justicia lo pondrán de manifiesto al interesado en el plazo de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 50 — Admisión a trámite ✱","q":[{"i":"7-33","p":"Ley Orgánica del Tribunal Constitucional. El recurso de amparo debe ser objeto de una decisión de admisión a trámite. La Sección, por _______ de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso solamente cuando concurran todos los siguientes requisitos.","o":["Mayoría simple.","Unanimidad.","Mayoría de dos tercios.","Mayoría cualificada de tres cuartos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Unanimidad</mark></span>Si hay mayoría pero no unanimidad, la Sección traslada la decisión a la Sala (art. 50.2). Según el <span class=\"ref-norma\">art. 50.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso solamente cuando concurran todos los siguientes requisitos\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7179","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. La Sección acordará mediante providencia la admisión, en todo o en parte, del recurso de amparo solamente cuando concurran todos los requisitos legales y lo decida:","o":["por unanimidad de sus miembros.","por mayoría de sus miembros.","por mayoría de dos tercios.","por decisión del Presidente de la Sección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por unanimidad de sus miembros</mark></span>El <span class=\"ref-norma\">art. 50.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-94","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Mediante qué tipo de resolución se podrá admitir o inadmitir un recurso de amparo?","o":["Auto.","Decreto.","Providencia.","Sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Providencia</mark></span>La inadmisión también es por providencia (art. 50.3); el recurso de súplica se resuelve mediante auto. Según el <span class=\"ref-norma\">art. 50.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7180","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Para admitir a trámite el recurso de amparo, el contenido del recurso debe justificar una decisión sobre el fondo en razón de su especial trascendencia constitucional, que se apreciará atendiendo a:","o":["la gravedad del perjuicio sufrido por el recurrente.","la existencia de doctrina contradictoria entre las Salas.","la relevancia social de los hechos que dieron lugar al recurso, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","su importancia para la interpretación de la Constitución, para su aplicación o para su general eficacia, y para la determinación del contenido y alcance de los derechos fundamentales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su importancia para la interpretación de la Constitución, para su aplicación o para su general eficacia, y para la determinación del contenido y alcance de los derechos fundamentales</mark></span>El <span class=\"ref-norma\">art. 50.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"que se apreciará atendiendo a su importancia para la interpretación de la Constitución, para su\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-148","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. Cuando la admisión a trámite del recurso de amparo, aun habiendo obtenido la mayoría, no alcance la unanimidad:","o":["La Sección acordará la inadmisión mediante providencia.","La Sección elevará la decisión al Pleno para su resolución.","La Sección trasladará la decisión a la Sala respectiva para su resolución.","Se entenderá admitido a trámite el recurso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sección trasladará la decisión a la Sala respectiva para su resolución</mark></span>El <span class=\"ref-norma\">art. 50.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Cuando la admisión a trámite, aun habiendo obtenido la mayoría, no alcance la unanimidad, la Sección trasladará la decisión a la Sala respectiva para su resolución.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-ia-7181","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Cuando la admisión a trámite, aun habiendo obtenido la mayoría, no alcance la unanimidad en la Sección:","o":["se archivará el recurso.","decidirá el Presidente de la Sección con voto de calidad, sin perjuicio de lo dispuesto en el Derecho nacional.","la Sección trasladará la decisión a la Sala respectiva para su resolución.","se elevará la cuestión al Pleno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Sección trasladará la decisión a la Sala respectiva para su resolución</mark></span>El <span class=\"ref-norma\">art. 50.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sección trasladará la decisión a la Sala respectiva para su resolución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-22","p":"Ley Orgánica del Tribunal Constitucional. Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán a: Señale la opción correcta.","o":["El demandante y el Ministerio Fiscal.","El demandante.","El demandante, el Ministerio Fiscal y el Defensor del Pueblo.","Quienes hayan sido parte en el proceso judicial correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El demandante y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal. Dichas providencias solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días. Este recurso se resolverá mediante auto, que no será susceptible de impugnación alguna.\"</span>."},{"i":"7-32","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las providencias de inadmisión, adoptadas por las Secciones o las Salas, solamente podrán ser recurridas:","o":["En súplica por el Ministerio Fiscal en el plazo de tres días.","En súplica por el Ministerio Fiscal en el plazo de cinco días.","En súplica por el Pleno en el plazo de tres días.","En súplica por el Pleno en el plazo de cinco días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En súplica por el Ministerio Fiscal en el plazo de tres días.</mark></span> El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, [...] solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días.\"</span> TEST 3"},{"i":"7-88","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo Constitucional. Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán:","o":["Al demandante.","Al Ministerio Fiscal.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 50.3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7203","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Señale la INCORRECTA sobre la admisión a trámite del recurso de amparo:","o":["La Sección admite el recurso por mayoría simple de sus miembros.","La admisión se acuerda mediante providencia.","Exige especial trascendencia constitucional.","Las providencias de inadmisión solo pueden ser recurridas en súplica por el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sección admite el recurso por mayoría simple de sus miembros</mark></span>El <span class=\"ref-norma\">art. 50 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-55","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿En qué plazo podrá el Ministerio Fiscal interponer un recurso ante la inadmisión a trámite de un recurso de amparo?","o":["Cinco días.","Tres días.","Siete días.","Diez días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Tres días</mark></span>El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal. Dichas providencias solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días. Este recurso se resolverá mediante auto, que no será susceptible de impugnación alguna.\"</span>."},{"i":"7-ia-7182","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Las providencias de inadmisión del recurso de amparo solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de:","o":["cinco días.","tres días.","diez días.","quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres días</mark></span>El <span class=\"ref-norma\">art. 50.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-130","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Mediante qué tipo de resolución se resolverá el recurso de súplica interpuesto por el Ministerio Fiscal ante la inadmisión del recurso de amparo?","o":["Providencia.","Sentencia.","Auto.","Decreto."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Auto</mark></span>El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal. Dichas providencias solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días. Este recurso se resolverá mediante auto, que no será susceptible de impugnación alguna.\"</span>."}]},{"a":"Artículo 53 — Fallos R7","q":[{"i":"7-149","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos:","o":["Estimación o desestimación del amparo.","Otorgamiento de amparo o denegación de amparo.","Admisión o inadmisión del amparo.","Nulidad o confirmación del acto impugnado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Otorgamiento de amparo o denegación de amparo</mark></span>El <span class=\"ref-norma\">art. 53 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos: a) Otorgamiento de amparo. b) Denegación de amparo.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado EXOF · R7 en tu temario)</em>"}]},{"a":"ARTS. 53 Y 55.1 · FALLOS Y PRONUNCIAMIENTOS DE LA SENTENCIA DE AMPARO","q":[{"i":"7-64","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Cuál de los siguientes se deberá pronunciar mediante sentencia en la resolución de los recursos de amparo?","o":["La Sala o, en su caso, la Sección.","El Pleno o, en su caso, la Sala o la Sección.","La Sección.","El Pleno o, en su caso, la Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala o, en su caso, la Sección</mark></span>El <span class=\"ref-norma\">art. 53 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos: a) Otorgamiento de amparo. b) Denegación de amparo.\"</span>."},{"i":"7-ia-7188","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Resolución del amparo. La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos:","o":["estimación, desestimación o inadmisión del amparo.","otorgamiento de amparo, denegación de amparo o archivo.","otorgamiento de amparo o remisión al Pleno.","otorgamiento de amparo o denegación de amparo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">otorgamiento de amparo o denegación de amparo</mark></span>El <span class=\"ref-norma\">art. 53 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) Otorgamiento de amparo. b) Denegación de amparo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 55 — Contenido de la sentencia de amparo ✱","q":[{"i":"7-44","p":"Ley Orgánica del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: señale la incorrecta.","o":["Establecimiento de una indemnización a favor del recurrente por el perjuicio ocasionado por la vulneración del derecho objeto de amparo.","Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos y libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","Reconocimiento del derecho o libertad pública.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Establecimiento de una indemnización a favor del recurrente por el perjuicio ocasionado por la vulneración del derecho objeto de amparo</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-15","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","El reconocimiento del derecho o de las libertades públicas, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-110","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la resolución de los recursos de amparo constitucional y sus efectos. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["Declaración de nulidad de la decisión, acto o resolución que hayan impedido o pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-114","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["Declaración de nulidad de la decisión, acto o resolución que hayan impedido o pleno ejercicio de los derechos o libertades protegidos.","Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-ia-7190","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia de amparo. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["declaración de nulidad de la norma aplicada, indemnización y restablecimiento del recurrente, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","declaración de nulidad de la decisión, acto o resolución, reconocimiento del derecho o libertad, y restablecimiento del recurrente en la integridad de su derecho.","reconocimiento del derecho, indemnización de daños y declaración de nulidad de la decisión.","declaración de inconstitucionalidad de la norma, nulidad del acto y condena en costas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">declaración de nulidad de la decisión, acto o resolución, reconocimiento del derecho o libertad, y restablecimiento del recurrente en la integridad de su derecho</mark></span>El <span class=\"ref-norma\">art. 55.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-28","p":"Ley Orgánica del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: señale la incorrecta.","o":["Reconocimiento de los derechos a las libertades y dependientes de recurrente, salvo a oposición del recurrente.","Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","Reconocimiento del derecho o libertas públicas, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de sus derechos o libertas con la adopción de las medidas apropiadas, en su caso, para su conservación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reconocimiento de los derechos a las libertades y dependientes de recurrente, salvo a oposición del recurrente</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-ia-7161","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedencia del recurso de amparo. En el amparo constitucional no pueden hacerse valer otras pretensiones que las dirigidas a:","o":["obtener una indemnización por los daños causados.","anular las normas aplicadas en la resolución impugnada.","restablecer o preservar los derechos o libertades por razón de los cuales se formuló el recurso.","depurar la responsabilidad disciplinaria de los funcionarios, en los términos que establezca el propio Reglamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">restablecer o preservar los derechos o libertades por razón de los cuales se formuló el recurso</mark></span>El <span class=\"ref-norma\">art. 41.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En el amparo constitucional no pueden hacerse valer otras pretensiones que las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7191","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia de amparo. En el supuesto de que el recurso de amparo debiera ser estimado porque la ley aplicada lesione derechos fundamentales o libertades públicas, se elevará la cuestión:","o":["al Pleno, con suspensión del plazo para dictar sentencia.","al Pleno, sin suspensión del plazo para dictar sentencia.","a la otra Sala, con suspensión del plazo para dictar sentencia.","al Tribunal Supremo, con suspensión del plazo para dictar sentencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Pleno, con suspensión del plazo para dictar sentencia</mark></span>El <span class=\"ref-norma\">art. 55.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"se elevará la cuestión al Pleno con suspensión del plazo para dictar\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 1 — Objeto y carácter R10","q":[{"i":"7-ia-7307","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, garantizado en la Constitución, será protegido civilmente frente a:","o":["las intromisiones ilegítimas de los poderes públicos exclusivamente, conforme al procedimiento que se establezca reglamentariamente.","las intromisiones ilegítimas que constituyan delito.","todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica.","las intromisiones ilegítimas de los medios de comunicación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica</mark></span>El <span class=\"ref-norma\">art. 1.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"será protegido civilmente frente a todo género de intromisiones ilegítimas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-1","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Disposiciones Generales. El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial.","o":["El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica.","El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible.","El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial</mark></span>El <span class=\"ref-norma\">art. 1.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial previsto en el artículo 9.º de esta Ley.\"</span>."},{"i":"7-ia-7308","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial previsto en la Ley. En cualquier caso, serán aplicables los criterios de esta Ley:","o":["para la determinación de la pena aplicable.","para la determinación de la responsabilidad civil derivada de delito.","para la determinación de la competencia judicial, sin perjuicio de lo dispuesto en el Derecho nacional.","para la determinación del plazo de prescripción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">para la determinación de la responsabilidad civil derivada de delito</mark></span>El <span class=\"ref-norma\">art. 1.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"serán aplicables los\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-84","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El derecho al honor, a la intimidad personal y familiar y a la propia imagen es: señale la INCORRECTA.","o":["Irrenunciable.","Imprescriptible.","Inalienable.","Inembargable."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Inembargable</mark></span>«Inembargable» no figura en el texto: es la falsa. Según el <span class=\"ref-norma\">art. 1.3 de la LO 1/1982</span>: <span class=\"ref-concepto\">\"El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible\"</span> (verificado con el texto del temario)."},{"i":"7-128","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El derecho al honor, a la intimidad personal y familiar y a la propia imagen es:","o":["Irrenunciable.","Inalienable.","Imprescriptible.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 1.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible.\"</span>."},{"i":"7-ia-7309","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. El derecho al honor, a la intimidad personal y familiar y a la propia imagen es:","o":["irrenunciable, inalienable e imprescriptible.","irrenunciable, transmisible e imprescriptible.","renunciable, inalienable e imprescriptible.","irrenunciable, inalienable y prescriptible a los cuatro años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">irrenunciable, inalienable e imprescriptible</mark></span>El <span class=\"ref-norma\">art. 1.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"es irrenunciable, inalienable e imprescriptible\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-61","p":"Ley Orgánica 1/1982, sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. En relación a los derechos al honor, a la intimidad personal y familiar y a la propia imagen, ¿Cuál tendrá una aplicación preferente, la protección penal o la civil?","o":["La protección civil.","La protección penal.","Se resolverán de forma independiente.","Se resolverá de forma conjunta, con preferencia sobre la protección civil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La protección penal</mark></span>Ojo: el art. 1.2 añade que el carácter delictivo no impide acudir a la tutela civil del art. 9. Según el <span class=\"ref-norma\">Preámbulo de la LO 1/1982</span>: <span class=\"ref-concepto\">\"en los casos que exista la protección penal tendrá ésta preferente aplicación, por ser sin duda la de más fuerte efectividad, si bien la responsabilidad civil derivada del delito se deberá fijar de acuerdo con los criterios que esta ley establece\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7310","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. La renuncia a la protección prevista en la Ley será nula, sin perjuicio de:","o":["los supuestos de autorización judicial, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","los supuestos de interés público.","los supuestos de consentimiento tácito.","los supuestos de autorización o consentimiento a que se refiere el artículo segundo de la Ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los supuestos de autorización o consentimiento a que se refiere el artículo segundo de la Ley</mark></span>El <span class=\"ref-norma\">art. 1.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La renuncia a la protección prevista en esta ley será nula, sin perjuicio de los supuestos de autorización o consentimiento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — Consentimiento de menores e incapaces ✱ R11","q":[{"i":"7-62","p":"Ley Orgánica 1/1982, sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. ¿De qué forma otorgarán el consentimiento los menores e incapaces cuando no dispongan suficientes condiciones de madurez?","o":["Mediante verba del Tribunal competente.","Mediante autorización expresa en presencia de su tutor, curador o defensor.","Mediante escrito por su representante legal.","Mediante anuencia del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Mediante escrito por su representante legal</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-ia-7306","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo, en el caso de la lesión producida antes del fallecimiento sin que el titular ejerciera las acciones, estas solo subsistirán:","o":["si lo solicita el cónyuge supérstite.","si no han transcurrido ochenta años.","si el Ministerio Fiscal lo estima conveniente, salvo que el Estado miembro afectado disponga otra cosa.","si no hubieran podido ser ejercitadas por aquél o por su representante legal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">si no hubieran podido ser ejercitadas por aquél o por su representante legal</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"sólo subsistirán éstas si no hubieran podido ser ejercitadas por aquél o por su representante legal\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-6","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil. En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de _______ el Ministerio Fiscal se opusiere, resolverá el juez.","o":["Cinco días","Siete días","Ocho días","Diez días"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ocho días</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-100","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. El consentimiento de los menores e incapaces; en los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si el Ministerio Fiscal se opusiere, resolverá el juez, en el plazo de:","o":["Cinco días.","Seis días.","Siete días.","Ocho días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ocho días</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-105","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. ¿Qué plazo tendrá el Ministerio Fiscal para oponerse al consentimiento de menores e incapaces otorgado mediante escrito de su representante?","o":["Ocho días.","Siete días.","Diez días.","Quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ocho días</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-134","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. ¿Qué ocurrirá si el Ministerio Fiscal se opone al consentimiento de menores e incapaces otorgado mediante escrito por su representante legal?","o":["Que dicho consentimiento quedará invalidado.","Que resolverá el Juez.","Que deberá personarse tanto el menor o incapaz como su representante legal en audiencia ante el Ministerio Fiscal.","Nada, pues la oposición del Ministerio Fiscal no produce efectos sobre la autorización otorgada por representante legal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que resolverá el Juez</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-ia-7316","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Consentimiento de menores e incapaces. En los restantes casos, el consentimiento de menores e incapaces habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere:","o":["quedará sin efecto el consentimiento.","resolverá el Juez.","resolverá la autoridad administrativa competente.","se entenderá denegado el consentimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">resolverá el Juez</mark></span>El <span class=\"ref-norma\">art. 3.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 — Acciones de protección de una persona fallecida ✱","q":[{"i":"7-92","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde:","o":["A quien esta haya designado a tal efecto en su testamento.","Al cónyuge.","Los ascendientes.","Los descendientes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A quien esta haya designado a tal efecto en su testamento</mark></span>El <span class=\"ref-norma\">art. 4.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien ésta haya designado a tal efecto en su testamento. La designación puede recaer en una persona jurídica.\"</span>. Solo en defecto de designación testamentaria (o fallecida la persona designada) están legitimados el cónyuge, descendientes, ascendientes y hermanos (art. 4.2)."},{"i":"7-ia-7305","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo, la protección en el caso de que la lesión se hubiera producido después del fallecimiento de una persona se atribuye, en primer lugar, a la persona que ésta hubiera designado:","o":["en su testamento.","en escritura pública notarial.","ante el Ministerio Fiscal.","en documento privado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en su testamento</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"de una persona a quien ésta hubiera designado en su testamento, en defecto de ella a los parientes supervivientes\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7317","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien ésta haya designado a tal efecto en su testamento. La designación puede recaer:","o":["en una persona jurídica.","únicamente en una persona física.","únicamente en un familiar.","únicamente en el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en una persona jurídica</mark></span>El <span class=\"ref-norma\">art. 4.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La designación puede recaer en una persona jurídica\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-3","p":"Ley Orgánica 1/1982, de 5 de mayo, sobre Protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien ésta haya designado a tal efecto en su testamento. La designación puede recaer en una persona jurídica. No existiendo designación o habiendo fallecido la persona designada, estarán legitimados para recabar la protección _______ de la persona afectada que viviesen al tiempo de su fallecimiento.","o":["El cónyuge.","Los descendientes.","Los ascendientes.","Todos son correctos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctos</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"estarán legitimados para recabar la protección el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento.\"</span>."},{"i":"7-ia-7318","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. No existiendo designación o habiendo fallecido la persona designada, estarán legitimados para recabar la protección:","o":["el cónyuge y los descendientes exclusivamente.","los parientes hasta el cuarto grado.","el cónyuge, los descendientes y los herederos testamentarios, conforme al procedimiento que se establezca reglamentariamente.","el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento</mark></span>El <span class=\"ref-norma\">art. 4.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"estarán legitimados para recabar la protección el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-132","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida, cuando no exista testamento, corresponde al cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que:","o":["Viviesen al tiempo de su fallecimiento.","Residiesen con él al tiempo de su fallecimiento.","Viviesen al tiempo de ejercer la acción civil.","Tuvieran un vínculo personal real con el fallecido."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Viviesen al tiempo de su fallecimiento</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"No existiendo designación o habiendo fallecido la persona designada, estarán legitimados para recabar la protección el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento.\"</span>."},{"i":"7-ia-7344","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. Señale la INCORRECTA sobre la protección civil del honor, la intimidad y la imagen de las personas fallecidas:","o":["Puede ejercerlas quien el fallecido haya designado en su testamento.","El Ministerio Fiscal puede ejercer las acciones sin límite temporal.","A falta de designación, están legitimados el cónyuge, descendientes, ascendientes y hermanos que vivieran al fallecimiento.","A falta de todos ellos, corresponde al Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Ministerio Fiscal puede ejercer las acciones sin límite temporal</mark></span>El <span class=\"ref-norma\">art. 4 (señale la incorrecta) de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-86","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien la represente, el ejercicio de las acciones de protección corresponderá al Ministerio Fiscal, que podrá actuar de oficio o a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento 1del afectado.","o":["Setenta años.","Ochenta años.","Noventa años.","Cien años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ochenta años</mark></span>El <span class=\"ref-norma\">art. 4.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"A falta de todos ellos, el ejercicio de las acciones de protección corresponderá al Ministerio Fiscal, que podrá actuar de oficio a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado.\"</span>."},{"i":"7-123","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde al Ministerio Fiscal, que podrá actuar de oficio o a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado.","o":["Setenta años.","Ochenta años.","Noventa años.","Cien años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ochenta años</mark></span>El <span class=\"ref-norma\">art. 4.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"A falta de todos ellos, el ejercicio de las acciones de protección corresponderá al Ministerio Fiscal, que podrá actuar de oficio a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado.\"</span>."},{"i":"7-ia-7319","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. A falta de todos los legitimados, el ejercicio de las acciones de protección de una persona fallecida corresponderá al Ministerio Fiscal, siempre que no hubieren transcurrido más de:","o":["cincuenta años desde el fallecimiento del afectado.","veinte años desde el fallecimiento del afectado.","ochenta años desde el fallecimiento del afectado.","cuatro años desde el fallecimiento del afectado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ochenta años desde el fallecimiento del afectado</mark></span>El <span class=\"ref-norma\">art. 4.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7320","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. En los supuestos de intromisión ilegítima en los derechos de las víctimas de un delito, estará legitimado para ejercer las acciones de protección:","o":["el Ministerio Fiscal exclusivamente.","el ofendido o perjudicado por el delito cometido, haya o no ejercido la acción penal o civil en el proceso penal precedente, y también en todo caso el Ministerio Fiscal.","el ofendido únicamente si ha ejercido la acción penal, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","el ofendido únicamente si ha ejercido la acción civil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el ofendido o perjudicado por el delito cometido, haya o no ejercido la acción penal o civil en el proceso penal precedente, y también en todo caso el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 4.4 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"estará legitimado para ejercer las acciones de protección el ofendido o perjudicado por el delito cometido, haya o no\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Intromisiones ilegítimas ✱","q":[{"i":"7-155","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo segundo de esta Ley, entre otras:","o":["La publicación de la imagen de una persona en actos públicos o en lugares abiertos al público, sin perjuicio de lo que establezcan los tratados internacionales, en los términos que determine la ley orgánica correspondiente.","La captación de la imagen de una persona que ejerza un cargo público durante un acto público.","El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.","La utilización de la caricatura de una persona de notoriedad pública conforme al uso social."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas</mark></span>El <span class=\"ref-norma\">art. 7 (apartados 1 y 2) de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo segundo de esta Ley: 1. El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.\"</span>"},{"i":"7-ia-7324","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima el emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para:","o":["difundir la imagen de las personas.","grabar o reproducir la vida íntima de las personas.","recopilar datos personales de las personas, en los términos que establezca el propio Reglamento.","localizar a las personas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">grabar o reproducir la vida íntima de las personas</mark></span>El <span class=\"ref-norma\">art. 7.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"apto para grabar o reproducir la vida íntima de las personas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-150","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. De la protección civil del honor, de la intimidad y de la propia imagen. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 2 de esta Ley: la utilización de aparatos de escucha, dispositivos ópticos, o de cualquier otro medio para el conocimiento de la vida íntima de las personas o de manifestaciones o cartas privadas:","o":["Destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción.","No destinadas a quien haga uso de tales medios, salvo su grabación o registro.","Únicamente cuando se produzca su difusión pública.","No destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"2. La utilización de aparatos de escucha, dispositivos ópticos, o de cualquier otro medio para el conocimiento de la vida íntima de las personas o de manifestaciones o cartas privadas no destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-9","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 2 de esta ley:","o":["La divulgación de hechos relativos a la vida privada de una persona o familia que afecten a su reputación y buen nombre, así como la revelación o publicación del contenido de cartas, memorias u otros escritos personales de carácter íntimo.","La revelación de datos privados de una persona o familia conocidos a través de la actividad profesional u oficial de quienes los revelen.","La utilización del delito por el condenado en sentencia penal firme para conseguir notoriedad pública u obtener provecho económico, o la divulgación de datos falsos sobre los hechos delictivos, cuando ello suponga el menoscabo de la dignidad de las víctimas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 7 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"1. El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.\"</span>. Los apartados 3 y 4 y el 8 del artículo 7 son también intromisiones ilegítimas; el 3 se refiere a escritos personales de carácter íntimo (no «público»)."},{"i":"7-ia-7325","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la divulgación de hechos relativos a la vida privada de una persona o familia que afecten:","o":["a su reputación y buen nombre, así como la revelación o publicación del contenido de cartas, memorias u otros escritos personales de carácter íntimo.","a su situación patrimonial y a su domicilio, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","a su salud y a su religión.","a su honor profesional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a su reputación y buen nombre, así como la revelación o publicación del contenido de cartas, memorias u otros escritos personales de carácter íntimo</mark></span>El <span class=\"ref-norma\">art. 7.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"que afecten a su reputación y buen nombre\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7326","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la revelación de datos privados de una persona o familia conocidos a través de:","o":["los medios de comunicación, sin perjuicio de lo dispuesto en el Derecho nacional.","las redes sociales.","terceras personas.","la actividad profesional u oficial de quien los revela."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la actividad profesional u oficial de quien los revela</mark></span>El <span class=\"ref-norma\">art. 7.4 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"conocidos a través de la actividad profesional u oficial de quien los revela\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-97","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por esta ley:","o":["El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.","La revelación de datos privados de una persona o familia conocidos a través de la actividad profesional u oficial de quien los revela.","La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>El <span class=\"ref-norma\">art. 7 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"4. La revelación de datos privados de una persona o familia conocidos a través de la actividad profesional u oficial de quien los revela. 5. La captación, reproducción o publicación por fotografía, filme, o cualquier otro procedimiento, de la imagen de una persona en lugares o momentos de su vida privada o fuera de ellos, salvo los casos previstos en el artículo octavo, dos. 6. La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga.\"</span>."},{"i":"7-ia-7328","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la utilización del nombre, de la voz o de la imagen de una persona para:","o":["fines informativos o periodísticos, en los términos que establezca el propio Reglamento.","fines publicitarios, comerciales o de naturaleza análoga.","fines científicos o culturales.","fines políticos o electorales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">fines publicitarios, comerciales o de naturaleza análoga</mark></span>El <span class=\"ref-norma\">art. 7.6 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7346","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Señale cuál NO tiene la consideración de intromisión ilegítima según el artículo siete de la Ley:","o":["La utilización de la voz de una persona para fines publicitarios sin su consentimiento.","La revelación de datos privados conocidos a través de la actividad profesional de quien los revela.","El emplazamiento de aparatos de escucha para grabar la vida íntima de las personas.","La captación de la imagen de un personaje público durante un acto público."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La captación de la imagen de un personaje público durante un acto público</mark></span>El <span class=\"ref-norma\">art. 7 (señale la incorrecta) de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"a) Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7329","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la imputación de hechos o la manifestación de juicios de valor a través de acciones o expresiones que lesionen la dignidad de otra persona, menoscabando:","o":["su fama o atentando contra su propia estimación.","su reputación profesional o su patrimonio, salvo que el Estado miembro afectado disponga otra cosa.","su honor familiar o su intimidad.","su libertad ideológica o su religión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su fama o atentando contra su propia estimación</mark></span>El <span class=\"ref-norma\">art. 7.7 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"menoscabando su fama o atentando contra su propia estimación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-43","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. En particular, el derecho a la propia imagen no impedirá su captación en un acto público, cuando se trate de personas que ejerzan: Señale la opción incorrecta.","o":["Un cargo público.","Una profesión de notoriedad.","Una profesión de proyección pública.","Una profesión en el ejercicio de funciones públicas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Una profesión en el ejercicio de funciones públicas</mark></span>El <span class=\"ref-norma\">art. 8.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En particular, el derecho a la propia imagen no impedirá: a) Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte durante un acto público o en lugares abiertos al público. b) La utilización de la caricatura de dichas personas, de acuerdo con el uso social. c) La información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca como meramente accesoria.\"</span>."},{"i":"7-ia-7330","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la utilización del delito por el condenado en sentencia penal firme para conseguir notoriedad pública u obtener provecho económico, o la divulgación de datos falsos sobre los hechos delictivos, cuando ello suponga:","o":["el menoscabo del honor del condenado.","la alteración del orden público.","la revelación de datos del procedimiento, conforme al procedimiento que se establezca reglamentariamente.","el menoscabo de la dignidad de las víctimas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el menoscabo de la dignidad de las víctimas</mark></span>El <span class=\"ref-norma\">art. 7.8 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando ello suponga el menoscabo de la dignidad de las víctimas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 8.2 · EL DERECHO A LA PROPIA IMAGEN NO IMPEDIRÁ","q":[{"i":"7-102","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La protección civil del honor, de la intimidad y de la propia imagen quedará delimitada:","o":["Por las leyes y por los usos sociales.","Por las leyes y su desarrollo normativo complementario.","Por las leyes y por las costumbres.","Por la situación jurídica y personal de cada persona."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por las leyes y por los usos sociales</mark></span>El <span class=\"ref-norma\">art. 8.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Podrá corresponder también a las Secciones el conocimiento y resolución de aquellos asuntos de amparo que la Sala correspondiente les defiera en los términos previstos en esta ley.\"</span>."},{"i":"7-107","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La protección civil del honor, de la intimidad y de la propia imagen. En particular, el derecho a la propia imagen no impedirá:","o":["La utilización de la caricatura de dichas personas, de acuerdo con el uso social.","La información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca como meramente accesoria.","Su captación, reproducción o publicación por cualquier medio, cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte durante un acto público o en lugares abiertos al público.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 8.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En particular, el derecho a la propia imagen no impedirá: a) Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte durante un acto público o en lugares abiertos al público. b) La utilización de la caricatura de dichas personas, de acuerdo con el uso social. c) La información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca como meramente accesoria.\"</span>."},{"i":"7-108","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. No se reputarán, con carácter general, intromisiones ilegítimas:","o":["La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga.","Las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley.","Aquellas actuaciones en las que no predomina un interés histórico, científico o cultural relevante.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley</mark></span>El <span class=\"ref-norma\">art. 8.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"No se reputará, con carácter general, intromisiones ilegítimas las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley, ni cuando predomine un interés histórico, científico o cultural relevante.\"</span>."},{"i":"7-ia-7331","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. No se reputarán, con carácter general, intromisiones ilegítimas las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley, ni cuando:","o":["predomine un interés económico o comercial relevante, sin perjuicio de lo dispuesto en el Derecho nacional.","exista consentimiento tácito del interesado.","predomine un interés histórico, científico o cultural relevante.","se trate de personas fallecidas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">predomine un interés histórico, científico o cultural relevante</mark></span>El <span class=\"ref-norma\">art. 8.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"ni cuando predomine un interés histórico, científico o cultural relevante\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7332","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. El derecho a la propia imagen no impedirá su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte:","o":["en cualquier lugar y momento.","durante un acto público o en lugares abiertos al público.","durante el ejercicio de su cargo o profesión.","en lugares públicos, con consentimiento previo, en los términos que establezca el propio Reglamento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">durante un acto público o en lugares abiertos al público</mark></span>El <span class=\"ref-norma\">art. 8.2.a de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"la imagen se capte durante un acto público o en lugares abiertos al público\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7333","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. El derecho a la propia imagen no impedirá la utilización de la caricatura de dichas personas:","o":["de acuerdo con el uso social.","con autorización de la persona caricaturizada.","siempre que no sea ofensiva.","siempre que se haga con fines periodísticos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de acuerdo con el uso social</mark></span>El <span class=\"ref-norma\">art. 8.2.b de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La utilización de la caricatura de dichas personas, de acuerdo con el uso social\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7334","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. El derecho a la propia imagen no impedirá la información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca:","o":["como elemento principal de la noticia.","con difuminado del rostro.","con consentimiento de la persona.","como meramente accesoria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">como meramente accesoria</mark></span>El <span class=\"ref-norma\">art. 8.2.c de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando la imagen de una persona determinada aparezca como meramente accesoria\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7335","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. Las excepciones relativas a personas con cargo público y a la caricatura no serán de aplicación respecto de:","o":["los menores de edad que ejerzan una profesión.","las personas fallecidas.","las autoridades o personas que desempeñen funciones que por su naturaleza necesiten el anonimato de la persona que las ejerza.","las personas que hayan sido condenadas por sentencia firme, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las autoridades o personas que desempeñen funciones que por su naturaleza necesiten el anonimato de la persona que las ejerza</mark></span>El <span class=\"ref-norma\">art. 8.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"no serán de aplicación respecto de las autoridades o personas que desempeñen funciones que por su naturaleza necesiten el anonimato\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 9.2 · TUTELA JUDICIAL: MEDIDAS NECESARIAS PARA PONER FIN A LA INTROMISIÓN","q":[{"i":"7-2","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Las acciones de protección frente a las intromisiones ilegítimas caducarán:","o":["Transcurridos cuatro años desde que el legitimado pudo ejercitarlas.","Transcurridos tres años desde que el legitimado pudo ejercitarlas.","Transcurridos cinco años desde que el legitimado pudo ejercitarlas.","Transcurridos ocho años desde que el legitimado pudo ejercitarlas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Transcurridos cuatro años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9.5 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas.\"</span>."},{"i":"7-10","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para, entre otros:","o":["Prevenir intromisiones inminentes o ulteriores.","La indemnización de los daños y perjuicios causados.","La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para: a) El restablecimiento del perjudicado en el pleno disfrute de sus derechos\"</span>."},{"i":"7-16","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá, sin perjuicio del derecho de réplica por el procedimiento legalmente previsto:","o":["La publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida.","La publicación siempre se hará realidad de la sentencia condenatoria a costa del condenado con el mismo la misma difusión pública que tuvo la intromisión ilícita","La referencia a la sentencia condenatoria a costa del condenado.","La referencia a la sentencia condenatoria a costa del condenado con el mismo la misma difusión pública que tuvo la intromisión ilícita"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida</mark></span>Según el <span class=\"ref-norma\">art. 9.2.a de la LO 1/1982</span>: <span class=\"ref-concepto\">\"En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá, sin perjuicio del derecho de réplica por el procedimiento legalmente previsto, la publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida\"</span> (verificado con el texto del temario)."},{"i":"7-71","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para:","o":["El restablecimiento del perjudicado en el pleno disfrute de sus derechos, con la declaración de la intromisión sufrida.","Prevenir intromisiones inminentes o ulteriores.","La indemnización de los daños y perjuicios causados.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"b) Prevenir intromisiones inminentes o ulteriores. c) La indemnización de los daños y perjuicios causados. d) La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.\"</span>."},{"i":"7-90","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos:","o":["Un año desde que el legitimado pudo ejercitarlas.","Dos años desde que el legitimado pudo ejercitarlas.","Tres años desde que el legitimado pudo ejercitarlas.","Cuatro años desde que el legitimado pudo ejercitarlas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuatro años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9.5 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas.\"</span>."},{"i":"7-112","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para: señale la INCORRECTA.","o":["El restablecimiento del perjudicado en el pleno disfrute de sus derechos, con la declaración de la intromisión sufrida, y cese inmediato de la misma y la reposición del estado anterior.","Prevenir únicamente las intromisiones inminentes, pero no las ulteriores.","La indemnización de los daños y perjuicios causados.","La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Prevenir únicamente las intromisiones inminentes, pero no las ulteriores</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"b) Prevenir intromisiones inminentes o ulteriores.\"</span>. La ley dice «inminentes o ulteriores»: se previenen las dos clases; la opción B, que excluye las ulteriores, es la incorrecta."},{"i":"7-119","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para:","o":["El restablecimiento del perjudicado en el pleno disfrute de sus derechos, con la declaración de la intromisión sufrida, el cese inmediato de la misma y la reposición del estado anterior.","Prevenir intromisiones inminentes o ulteriores.","La indemnización de los daños y perjuicios causados.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"b) Prevenir intromisiones inminentes o ulteriores. c) La indemnización de los daños y perjuicios causados. d) La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.\"</span>."},{"i":"7-151","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. De la protección civil del honor, de la intimidad y de la propia imagen. Se presumirá siempre que se acredite la intromisión ilegítima:","o":["La existencia de perjuicio.","La mala fe del causante.","La existencia de daño patrimonial.","La culpa del medio de difusión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La existencia de perjuicio</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La existencia de perjuicio se presumirá siempre que se acredite la intromisión ilegítima.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado R13 en tu temario)</em>"},{"i":"7-ia-7336","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. La tutela judicial frente a las intromisiones ilegítimas podrá recabarse por las vías procesales ordinarias o por el procedimiento previsto en la Constitución para la protección de los derechos fundamentales. También podrá acudirse:","o":["a la Agencia Española de Protección de Datos.","cuando proceda, al recurso de amparo ante el Tribunal Constitucional.","al Defensor del Pueblo con carácter vinculante.","a la jurisdicción contencioso-administrativa en todo caso, sin perjuicio de lo dispuesto en el Derecho nacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando proceda, al recurso de amparo ante el Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 9.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"También podrá acudirse, cuando proceda, al recurso de amparo ante el Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7337","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para el restablecimiento del perjudicado en el pleno disfrute de sus derechos, prevenir intromisiones inminentes o ulteriores, la indemnización de los daños y perjuicios y:","o":["la apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.","la imposición de una sanción administrativa al infractor, en los términos que establezca el propio Reglamento.","la retirada de la licencia del medio de comunicación.","la inhabilitación del infractor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos</mark></span>El <span class=\"ref-norma\">art. 9.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7338","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá, sin perjuicio del derecho de réplica, la publicación total o parcial de la sentencia condenatoria:","o":["a costa del perjudicado en un medio de su elección.","a costa del Estado en el «Boletín Oficial del Estado», salvo que el Estado miembro afectado disponga otra cosa.","a costa del condenado en un diario de tirada nacional.","a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida</mark></span>El <span class=\"ref-norma\">art. 9.2.a de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"la publicación total o parcial de la sentencia condenatoria a costa del condenado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7339","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. La existencia de perjuicio se presumirá siempre que se acredite la intromisión ilegítima. La indemnización se extenderá al daño moral, que se valorará atendiendo a las circunstancias del caso y a la gravedad de la lesión, teniendo en cuenta, en su caso:","o":["la capacidad económica del causante de la lesión, conforme al procedimiento que se establezca reglamentariamente.","el beneficio obtenido por el infractor.","la difusión o audiencia del medio a través del que se haya producido.","la notoriedad pública del perjudicado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la difusión o audiencia del medio a través del que se haya producido</mark></span>El <span class=\"ref-norma\">art. 9.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"se tendrá en cuenta, en su caso, la difusión o audiencia del medio a través del que se haya producido\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7340","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. En los casos del artículo sexto, la indemnización por el daño moral:","o":["corresponderá al Ministerio Fiscal.","se entenderá comprendida en la herencia del perjudicado.","corresponderá a los descendientes en todo caso, sin perjuicio de lo dispuesto en el Derecho nacional.","se destinará a fines de interés general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se entenderá comprendida en la herencia del perjudicado</mark></span>El <span class=\"ref-norma\">art. 9.4 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los casos del artículo sexto, la indemnización se entenderá comprendida en la herencia del perjudicado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7341","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos:","o":["cuatro años desde que el legitimado pudo ejercitarlas.","un año desde que el legitimado pudo ejercitarlas, en los términos que establezca el propio Reglamento.","cinco años desde la intromisión.","dos años desde la intromisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuatro años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9.5 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7345","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. Señale la INCORRECTA sobre la tutela judicial de los derechos al honor, la intimidad y la propia imagen:","o":["Las acciones caducan transcurridos seis años desde que el legitimado pudo ejercitarlas.","La existencia de perjuicio se presume siempre que se acredite la intromisión ilegítima, sin perjuicio de lo dispuesto en el Derecho nacional.","La indemnización se extiende al daño moral.","Puede acudirse, cuando proceda, al recurso de amparo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las acciones caducan transcurridos seis años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9 (señale la incorrecta) de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9 — Tutela judicial ✱ R13","q":[{"i":"7-36","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá la publicación total o parcial de la sentencia condenatoria a costa del condenado: Señale la opción correcta.","o":["Con al menos la misma difusión pública que tuvo la intromisión sufrida.","Con la misma difusión pública que tuvo la intromisión sufrida, debiendo proyectarse en forma específica en los mismos entornos en que fueron divulgadas.","Con una difusión pública superior a la que tuvo la intromisión sufrida, a efectos de que pueda alcanzar al menos a los mismos que tuvieron conocimiento de la intromisión.","Con una difusión pública."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con al menos la misma difusión pública que tuvo la intromisión sufrida</mark></span>Según el <span class=\"ref-norma\">art. 9.2.a de la LO 1/1982</span>: <span class=\"ref-concepto\">\"la publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida\"</span> (verificado con el texto del temario)."}]},{"a":"Artículo 2 — Ámbito de protección y consentimiento ✱","q":[{"i":"7-5","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Disposiciones Generales. El consentimiento del titular del derecho será revocable en cualquier momento:","o":["No indemnizando en su caso, los daños y perjuicios causados.","Pudiendo indemnizar en su caso, los daños y perjuicios causados, pero no las expectativas justificadas.","Pero habrán de indemnizarse en caso, los daños y perjuicios causados, incluyendo en ellos cualquier tipo de expectativas.","Pero habrán de indemnizarse, en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Pero habrán de indemnizarse, en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas</mark></span>Son expectativas JUSTIFICADAS, no «cualquier tipo de expectativas». Según el <span class=\"ref-norma\">art. 2.3 de la LO 1/1982</span>: <span class=\"ref-concepto\">\"El consentimiento a que se refiere el párrafo anterior será revocable en cualquier momento, pero habrán de indemnizarse en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7311","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. La protección civil del honor, de la intimidad y de la propia imagen quedará delimitada por las leyes y por los usos sociales atendiendo:","o":["al criterio exclusivo del juez en cada caso.","a la notoriedad pública de cada persona.","al ámbito que, por sus propios actos, mantenga cada persona reservado para sí misma o su familia.","a los criterios de los códigos deontológicos profesionales, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al ámbito que, por sus propios actos, mantenga cada persona reservado para sí misma o su familia</mark></span>El <span class=\"ref-norma\">art. 2.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"delimitada por las leyes y por los usos sociales atendiendo al ámbito que, por sus propios\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7312","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. No se apreciará la existencia de intromisión ilegítima en el ámbito protegido cuando estuviere expresamente autorizada por Ley o cuando el titular del derecho hubiere otorgado su consentimiento:","o":["tácito.","expreso.","verbal.","presunto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">expreso</mark></span>El <span class=\"ref-norma\">art. 2.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando el titular del derecho hubiere otorgado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7313","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. Tampoco se apreciará intromisión ilegítima, por imperativo de la Constitución, cuando se trate de:","o":["opiniones manifestadas por Diputados o Senadores en el ejercicio de sus funciones.","opiniones manifestadas por miembros del Gobierno en el ejercicio de sus funciones, sin perjuicio de lo dispuesto en el Derecho nacional.","opiniones manifestadas por Magistrados en sus resoluciones.","opiniones manifestadas por miembros de las Asambleas autonómicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">opiniones manifestadas por Diputados o Senadores en el ejercicio de sus funciones</mark></span>El <span class=\"ref-norma\">art. 2.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando se trate de opiniones manifestadas por Diputados o Senadores en el ejercicio\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7314","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Ámbito de la protección. El consentimiento del titular del derecho será revocable en cualquier momento, pero habrán de indemnizarse, en su caso:","o":["los daños materiales causados, excluyendo el lucro cesante, en los términos que establezca el propio Reglamento.","los gastos de publicidad realizados.","los daños morales exclusivamente.","los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas</mark></span>El <span class=\"ref-norma\">art. 2.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"pero habrán de indemnizarse en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional","q":[{"i":"7-7","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las peticiones de indemnización, que se sustanciarán por el trámite de los incidentes, deberán presentarse dentro del plazo de _______ a partir de la publicación de la sentencia del Tribunal Constitucional.","o":["Un mes.","Tres meses.","Seis meses.","Un año."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un año</mark></span>Según el <span class=\"ref-norma\">art. 58.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las peticiones de indemnización [...] deberán presentarse dentro del plazo de un año a partir de la publicación de la sentencia del Tribunal Constitucional\"</span> (verificado con el texto del temario)."},{"i":"7-53","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes: Señale la opción correcta.","o":["Al menos, dos tercios de los miembros que en cada momento lo compongan.","Más de dos tercios de los miembros que componen el Pleno.","Como mínimo tres quintos de los miembros que compongan cada una de las Salas.","En todo caso, tres quintos de los miembros definidos en el artículo 5 de esta Ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al menos, dos tercios de los miembros que en cada momento lo compongan</mark></span>El <span class=\"ref-norma\">art. 14 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes, al menos, dos tercios de los miembros que en cada momento lo compongan.\"</span>."},{"i":"7-56","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Recurso de amparo. Será competente para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión: Señale la respuesta correcta.","o":["Los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas.","El letrado de la Administración de Justicia del Tribunal Constitucional.","El Presidente de la Sección que conozca del asunto.","El Magistrado-Ponente que conozca del asunto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas</mark></span>Según el <span class=\"ref-norma\">art. 58.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Serán competentes para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas\"</span> (verificado con el texto del temario)."},{"i":"7-58","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Quién nombra al Presidente del Tribunal Constitucional?","o":["El Consejo de Estado.","El Ministro de Justicia.","El Rey.","El Tribunal en Pleno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Rey</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El nombre del elegido se elevará al Rey para su nombramiento por un período de tres años, expirado el cual podrá ser reelegido por una sola vez.\"</span>."},{"i":"7-63","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿De qué forma se encajan los presupuestos del Tribunal Constitucional en los Presupuestos Generales del Estado?","o":["Se integra como una sección independiente dentro de los Presupuestos Generales del Estado.","Se integra como una sección dependiente dentro de los Presupuestos Generales del Estado.","Se integra de forma genérica en los Presupuestos Generales del Estado.","No se encuentran integrados en los Presupuestos Generales del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se integra como una sección independiente dentro de los Presupuestos Generales del Estado</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>."},{"i":"7-82","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Los acuerdos de las Secciones requerirán la presencia de:","o":["Cuatro miembros, salvo que exista discrepancia, requiriéndose entonces la de cinco miembros.","Dos tercios de los miembros que en cada momento la compongan.","La mitad de los miembros que en cada momento la compongan.","Dos miembros, salvo que exista discrepancia, requiriéndose entonces la de tres miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Dos miembros, salvo que exista discrepancia, requiriéndose entonces la de tres miembros</mark></span>Las Secciones tienen tres miembros (el Presidente o quien le sustituya y dos Magistrados). Según el <span class=\"ref-norma\">art. 14 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"En las Secciones se requerirá la presencia de dos miembros, salvo que haya discrepancia, requiriéndose entonces la de sus tres miembros\"</span> (verificado con el texto del temario)."},{"i":"7-83","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes:","o":["Al menos, un tercio de sus miembros.","Al menos, un cuarto de sus miembros.","Al menos, un quinto de sus miembros.","Al menos, dos tercios de sus miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al menos, dos tercios de sus miembros</mark></span>El <span class=\"ref-norma\">art. 14 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes, al menos, dos tercios de los miembros que en cada momento lo compongan.\"</span>."},{"i":"7-87","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Cuál de las siguientes funciones NO se atribuye al Presidente del Tribunal Constitucional?","o":["Ejerce la representación del Tribunal.","Aprueba los presupuestos.","Convoca las Salas.","Adopta medidas precisas para el funcionamiento de las Secciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Aprueba los presupuestos</mark></span>Los presupuestos los elabora el Tribunal en Pleno (art. 10.3), no el Presidente. Según el <span class=\"ref-norma\">art. 15 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas; adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones [...]\"</span> (verificado con el texto del temario)."},{"i":"7-93","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. En relación con la tramitación de los recursos de amparo constitucional: señale la INCORRECTA.","o":["Las providencias de inadmisión, solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días.","Cuando en la demanda de amparo concurran uno o varios defectos de subsanables, de no producirse la subsanación dentro del plazo fijado en dicho precepto, la Sección acordará la inadmisión mediante providencia, contra la cual no cabrá recurso alguno.","Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que emanó la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en un plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.","El órgano, la autoridad, Juez o Tribunal avocará de inmediato del requerimiento, cumplimentará el envío dentro del plazo y limitará a emplazar a quienes fueron parte en el procedimiento antecedente para que puedan comparecer en el proceso constitucional en el plazo de diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El órgano, la autoridad, Juez o Tribunal avocará de inmediato del requerimiento, cumplimentará el envío dentro del plazo y limitará a emplazar a quienes fueron parte en el procedimiento antecedente para que puedan comparecer en el proceso constitucional en el plazo de diez días</mark></span>«Avocará» y «se limitará a emplazar» alteran el texto (acusa recibo, cumplimenta el envío y emplaza). Según el <span class=\"ref-norma\">art. 51 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El órgano, autoridad, Juez o Tribunal acusará inmediato recibo del requerimiento, cumplimentará el envío dentro del plazo señalado y emplazará a quienes fueron parte en el procedimiento antecedente\"</span> (verificado con el texto del temario)."},{"i":"7-116","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal en Pleno conoce de los siguientes asuntos, entre otros: señale la INCORRECTA.","o":["De los recursos de inconstitucionalidad contra las leyes y demás disposiciones con valor de ley, incluidos los de mera aplicación de doctrina.","De las cuestiones de constitucionalidad que reserve para sí; las demás deberán deferirse a las Salas según un turno objetivo.","De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de las de éstas entre sí.","De los conflictos en defensa de la autonomía local."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De los recursos de inconstitucionalidad contra las leyes y demás disposiciones con valor de ley, incluidos los de mera aplicación de doctrina</mark></span>El <span class=\"ref-norma\">art. 10.1.b) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) De los recursos de inconstitucionalidad contra las leyes y demás disposiciones con valor de ley, excepto los de mera aplicación de doctrina, cuyo conocimiento podrá atribuirse a las Salas en el trámite de admisión.\"</span>. La opción A dice «inclusive» los de mera aplicación de doctrina, cuando la ley los EXCEPTÚA; por eso es la incorrecta."},{"i":"7-124","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que emanó la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en un plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.","o":["En el plazo que no podrá exceder de diez días.","En el plazo que no podrá exceder de veinte días.","En el plazo que no podrá exceder de quince días.","En el plazo que no podrá exceder de cinco días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo que no podrá exceder de diez días</mark></span>El <span class=\"ref-norma\">art. 51.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.\"</span>."},{"i":"7-136","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal en Pleno elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento. El nombre del elegido se elevará al Rey para su nombramiento por un periodo de:","o":["Tres años, y podrá ser reelegido por una sola vez.","Tres años y no podrá ser reelegido.","Cinco años y podrá ser reelegido.","Cinco años y no podrá ser reelegido."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres años, y podrá ser reelegido por una sola vez</mark></span>Según el <span class=\"ref-norma\">art. 9.3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El nombre del elegido se elevará al Rey para su nombramiento por un período de tres años, expirado el cual podrá ser reelegido por una sola vez\"</span> (verificado con el texto del temario)."},{"i":"7-142","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. Las resoluciones del Tribunal Constitucional:","o":["Podrán ser enjuiciadas por el Tribunal Supremo cuando afecten a la legalidad ordinaria.","Podrán ser revisadas por el Pleno del Consejo General del Poder Judicial.","Solo podrán ser enjuiciadas por el Tribunal Europeo de Derechos Humanos.","No podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las resoluciones del Tribunal Constitucional no podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-143","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal en Pleno conoce de cualquier otro asunto que sea competencia del Tribunal pero recabe para sí el Pleno, a propuesta de:","o":["El Presidente o de tres Magistrados.","El Presidente o de dos Magistrados.","El Vicepresidente o de tres Magistrados.","La mayoría absoluta de los Magistrados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Presidente o de tres Magistrados</mark></span>El <span class=\"ref-norma\">art. 10.1.n) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"n) De cualquier otro asunto que sea competencia del Tribunal pero recabe para sí el Pleno, a propuesta del Presidente o de tres Magistrados\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-144","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. Las violaciones de los derechos y libertades originadas por disposiciones, actos jurídicos, omisiones o simple vía de hecho del Gobierno o de sus autoridades o funcionarios, o de los órganos ejecutivos colegiados de las comunidades autónomas o de sus autoridades o funcionarios o agentes, podrán dar lugar al recurso de amparo:","o":["En el plazo de tres meses desde que sean firmes.","Directamente, sin necesidad de agotar la vía judicial.","Una vez que se haya agotado la vía judicial procedente.","Una vez agotada la vía administrativa previa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una vez que se haya agotado la vía judicial procedente</mark></span>El <span class=\"ref-norma\">art. 43.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán dar lugar al recurso de amparo una vez que se haya agotado la vía judicial procedente\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado EXOF en tu temario)</em>"},{"i":"7-146","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. En el recurso de amparo frente a violaciones originadas por el Gobierno o sus autoridades, el recurso sólo podrá fundarse en la infracción:","o":["Por cualquier acto administrativo de los preceptos legales que desarrollan los derechos fundamentales.","Por una resolución no firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo.","De los Tratados internacionales sobre derechos humanos ratificados por España.","Por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo</mark></span>El <span class=\"ref-norma\">art. 43.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso sólo podrá fundarse en la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-152","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Tribunal en Pleno. El Tribunal en Pleno conoce de las cuestiones de constitucionalidad que reserve para sí; las demás:","o":["Deberán elevarse al Tribunal Supremo para su resolución definitiva.","Se resolverán por la Sección que designe el Presidente en cada caso.","Podrán deferirse a las Salas a propuesta del Fiscal General del Estado.","Deberán deferirse a las Salas según un turno objetivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Deberán deferirse a las Salas según un turno objetivo</mark></span>El <span class=\"ref-norma\">art. 10.1.c) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"c) De las cuestiones de constitucionalidad que reserve para sí; las demás deberán deferirse a las Salas según un turno objetivo.\"</span>"},{"i":"7-153","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Tribunal en Pleno. El Tribunal en Pleno conoce de los conflictos constitucionales de competencia:","o":["Entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.","Entre los órganos constitucionales del Estado y las Comunidades Autónomas.","Entre el Estado y las Entidades locales o de éstas entre sí.","Entre las Comunidades Autónomas y los órganos del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Entre el Estado y las Comunidades Autónomas o de los de éstas entre sí</mark></span>El <span class=\"ref-norma\">art. 10.1.d) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"d) De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.\"</span>"},{"i":"7-ia-7004","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá del recurso de amparo por violación de los derechos y libertades públicos relacionados en:","o":["el artículo cincuenta y tres, uno, de la Constitución.","el artículo cincuenta y tres, dos, de la Constitución.","el artículo ciento sesenta y uno, uno, de la Constitución.","el artículo catorce de la Constitución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el artículo cincuenta y tres, dos, de la Constitución</mark></span>El <span class=\"ref-norma\">art. 2.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo cincuenta y tres, dos, de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7008","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de las impugnaciones previstas en el número dos del artículo ciento sesenta y uno de la Constitución, esto es:","o":["de las leyes y disposiciones con fuerza de ley del Estado.","de las disposiciones y resoluciones adoptadas por los órganos de las Comunidades Autónomas.","de los actos de los Entes locales.","de las resoluciones de los Tribunales Superiores de Justicia, salvo que el Estado miembro afectado disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de las disposiciones y resoluciones adoptadas por los órganos de las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 2.1.f de LOTC</span> dispone: <span class=\"ref-concepto\">\"De las impugnaciones previstas en el número dos del artículo ciento sesenta y uno de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7013","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. El Tribunal Constitucional delimitará el ámbito de su jurisdicción y adoptará cuantas medidas sean necesarias para preservarla, incluyendo:","o":["la declaración de nulidad de aquellos actos o resoluciones que la menoscaben.","la suspensión de los magistrados que la menoscaben, salvo que el Estado miembro afectado disponga otra cosa.","la remisión de testimonio al Ministerio Fiscal.","la apertura de un procedimiento sancionador."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la declaración de nulidad de aquellos actos o resoluciones que la menoscaben</mark></span>El <span class=\"ref-norma\">art. 4.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"incluyendo la declaración de nulidad de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7014","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. Las resoluciones del Tribunal Constitucional:","o":["podrán ser revisadas por el Tribunal Supremo en casación.","podrán ser enjuiciadas por el Tribunal Europeo de Derechos Humanos en todo caso.","podrán ser anuladas por el Pleno del Consejo General del Poder Judicial.","no podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no podrán ser enjuiciadas por ningún órgano jurisdiccional del Estado</mark></span>El <span class=\"ref-norma\">art. 4.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Las resoluciones del Tribunal Constitucional no podrán ser enjuiciadas por ningún\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7015","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. Cuando el Tribunal Constitucional anule un acto o resolución que menoscabe su jurisdicción, lo ha de hacer motivadamente y previa audiencia:","o":["al Gobierno y al órgano autor del acto o resolución.","al Consejo General del Poder Judicial y al Ministerio Fiscal, conforme al procedimiento que se establezca reglamentariamente.","al Ministerio Fiscal y al órgano autor del acto o resolución.","a las partes y al Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Ministerio Fiscal y al órgano autor del acto o resolución</mark></span>El <span class=\"ref-norma\">art. 4.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"lo ha de hacer motivadamente y previa audiencia al Ministerio Fiscal y al órgano autor del acto o resolución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7024","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. El Tribunal en Pleno elige de entre sus miembros a su Presidente por votación:","o":["pública, y propone al Rey su nombramiento, sin perjuicio de lo dispuesto en el Derecho nacional.","secreta, y propone al Rey su nombramiento.","secreta, y lo nombra directamente.","pública, y lo comunica a las Cámaras."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">secreta, y propone al Rey su nombramiento</mark></span>El <span class=\"ref-norma\">art. 9.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7025","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. En la elección del Presidente, en primera votación se requerirá la mayoría absoluta. Si ésta no se alcanzase, se procederá a una segunda votación en la que:","o":["resultará elegido quien obtuviese mayor número de votos.","se exigirá la mayoría de tres quintos.","se exigirá de nuevo la mayoría absoluta.","resultará elegido el Magistrado más antiguo, en los términos que establezca el propio Reglamento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">resultará elegido quien obtuviese mayor número de votos</mark></span>El <span class=\"ref-norma\">art. 9.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en la que resultará elegido quien obtuviese mayor\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7026","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. En caso de empate en la segunda votación para elegir Presidente, se efectuará una última votación y si éste se repitiese, será propuesto:","o":["el de mayor edad y, en caso de igualdad, el más antiguo, salvo que el Estado miembro afectado disponga otra cosa.","el que designe el Rey.","el que decida el Pleno por sorteo.","el de mayor antigüedad en el cargo y, en caso de igualdad, el de mayor edad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el de mayor antigüedad en el cargo y, en caso de igualdad, el de mayor edad</mark></span>El <span class=\"ref-norma\">art. 9.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"será propuesto el de mayor antigüedad en el cargo y en caso de igualdad el de mayor edad\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7027","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. El Presidente del Tribunal Constitucional es nombrado por el Rey por un período de tres años, expirado el cual podrá ser reelegido:","o":["por dos veces.","sin limitación.","por una sola vez.","por una sola vez, con mayoría de dos tercios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por una sola vez</mark></span>El <span class=\"ref-norma\">art. 9.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"por un período de tres años, expirado el cual podrá ser reelegido por una sola vez\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7028","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente y el Vicepresidente. El Tribunal en Pleno elegirá entre sus miembros, por el mismo procedimiento y por el mismo período de tres años, un Vicepresidente, al que incumbe:","o":["presidir el Pleno y la Sala Primera.","sustituir al Presidente en caso de vacante, ausencia u otro motivo legal y presidir la Sala Segunda.","convocar las Salas y nombrar a los letrados.","representar al Tribunal ante las Cortes Generales, conforme al procedimiento que se establezca reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sustituir al Presidente en caso de vacante, ausencia u otro motivo legal y presidir la Sala Segunda</mark></span>El <span class=\"ref-norma\">art. 9.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"un Vicepresidente, al que incumbe sustituir al Presidente en caso de vacante, ausencia u otro motivo legal y\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7029","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno conoce de la constitucionalidad o inconstitucionalidad:","o":["de los tratados internacionales.","de los reglamentos del Gobierno.","de los actos de las Cortes Generales.","de los convenios de las Comunidades Autónomas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de los tratados internacionales</mark></span>El <span class=\"ref-norma\">art. 10.1.a de LOTC</span> dispone: <span class=\"ref-concepto\">\"De la constitucionalidad o inconstitucionalidad de los tratados internacionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7030","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno conoce de las cuestiones de constitucionalidad que reserve para sí; las demás deberán deferirse a las Salas:","o":["a propuesta del Presidente.","previo informe del Ministerio Fiscal.","por sorteo entre los Magistrados.","según un turno objetivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">según un turno objetivo</mark></span>El <span class=\"ref-norma\">art. 10.1.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"las demás deberán deferirse a las Salas según un turno objetivo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7031","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno conoce de los recursos previos de inconstitucionalidad contra:","o":["Proyectos de Ley Orgánica y Proyectos de Ley de Presupuestos, sin perjuicio de lo dispuesto en el Derecho nacional.","Proyectos de Decreto-ley y de Decreto legislativo.","Proyectos de Estatutos de Autonomía y contra Propuestas de Reforma de los Estatutos de Autonomía.","Tratados internacionales antes de su ratificación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Proyectos de Estatutos de Autonomía y contra Propuestas de Reforma de los Estatutos de Autonomía</mark></span>El <span class=\"ref-norma\">art. 10.1.d bis de LOTC</span> dispone: <span class=\"ref-concepto\">\"De los recursos previos de inconstitucionalidad contra Proyectos de Estatutos de Autonomía y contra Propuestas de Reforma de los Estatutos de Autonomía\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7032","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Pleno conoce de cualquier otro asunto que sea competencia del Tribunal pero recabe para sí, a propuesta:","o":["del Presidente o de dos Magistrados.","del Presidente o de tres Magistrados.","del Vicepresidente o de un Magistrado.","del Presidente o de cuatro Magistrados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del Presidente o de tres Magistrados</mark></span>El <span class=\"ref-norma\">art. 10.1.n de LOTC</span> dispone: <span class=\"ref-concepto\">\"a propuesta del Presidente o de tres Magistrados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7033","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra:","o":["como una sección independiente dentro de los Presupuestos Generales del Estado.","como un anexo del presupuesto del Consejo General del Poder Judicial, en los términos que establezca el propio Reglamento.","como una partida del Ministerio de Justicia.","como un presupuesto separado aprobado por las Cortes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">como una sección independiente dentro de los Presupuestos Generales del Estado</mark></span>El <span class=\"ref-norma\">art. 10.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"que se integra como una sección independiente dentro de los\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7034","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias de las Salas. Las Salas del Tribunal Constitucional conocerán de los asuntos que, atribuidos a la justicia constitucional, no sean:","o":["de la competencia de las Secciones.","objeto de recurso de amparo.","de la competencia del Presidente.","de la competencia del Pleno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de la competencia del Pleno</mark></span>El <span class=\"ref-norma\">art. 11 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Las Salas del Tribunal Constitucional conocerán de los asuntos que, atribuidos a la justicia constitucional, no sean de la competencia del Pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7037","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Quórum. El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes, al menos, dos tercios de los miembros que en cada momento lo compongan. En las Secciones se requerirá la presencia de dos miembros, salvo que haya discrepancia, requiriéndose entonces:","o":["la de sus tres miembros.","la del Presidente de la Sala.","la de dos tercios de la Sala.","la de todos los miembros de la Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la de sus tres miembros</mark></span>El <span class=\"ref-norma\">art. 14 de LOTC</span> dispone: <span class=\"ref-concepto\">\"salvo que haya discrepancia, requiriéndose entonces la de sus tres miembros\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7039","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. Mediante los procedimientos de declaración de inconstitucionalidad, el Tribunal Constitucional garantiza la primacía de la Constitución y enjuicia:","o":["la legalidad de los reglamentos y actos administrativos.","la compatibilidad de las leyes con el Derecho de la Unión, sin perjuicio de lo dispuesto en el Derecho nacional.","la conformidad o disconformidad con ella de las Leyes, disposiciones o actos impugnados.","la adecuación de las leyes a los tratados internacionales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la conformidad o disconformidad con ella de las Leyes, disposiciones o actos impugnados</mark></span>El <span class=\"ref-norma\">art. 27.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"garantiza la primacía de la Constitución y enjuicia la conformidad o disconformidad con ella de las Leyes, disposiciones o actos impugnados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7040","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. Son susceptibles de declaración de inconstitucionalidad, entre otros:","o":["los reglamentos del Gobierno.","los Reglamentos de las Cámaras y de las Cortes Generales.","las sentencias del Tribunal Supremo.","las resoluciones del Consejo General del Poder Judicial, en los términos que establezca el propio Reglamento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los Reglamentos de las Cámaras y de las Cortes Generales</mark></span>El <span class=\"ref-norma\">art. 27.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"d) Los Reglamentos de las Cámaras y de las Cortes Generales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7041","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. En el caso de los Decretos legislativos, la competencia del Tribunal se entiende sin perjuicio de lo previsto en:","o":["el número seis del artículo ochenta y dos de la Constitución.","el número seis del artículo ochenta y uno de la Constitución, salvo que el Estado miembro afectado disponga otra cosa.","el artículo ochenta y seis de la Constitución.","el artículo ochenta y cuatro de la Constitución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el número seis del artículo ochenta y dos de la Constitución</mark></span>El <span class=\"ref-norma\">art. 27.2.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"la competencia del Tribunal se entiende sin perjuicio de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7042","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. Para apreciar la conformidad o disconformidad con la Constitución de una Ley, el Tribunal considerará, además de los preceptos constitucionales:","o":["los tratados internacionales ratificados por España, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","la jurisprudencia del Tribunal Supremo.","los reglamentos que desarrollen la ley impugnada.","las Leyes que, dentro del marco constitucional, se hubieran dictado para delimitar las competencias del Estado y las Comunidades Autónomas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las Leyes que, dentro del marco constitucional, se hubieran dictado para delimitar las competencias del Estado y las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 28.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las Leyes que, dentro del marco constitucional, se hubieran dictado para delimitar las competencias del Estado y las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7043","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. El Tribunal podrá declarar inconstitucionales los preceptos de un Decreto-ley, Decreto legislativo o Ley no orgánica que regulen materias reservadas a Ley Orgánica, por infracción:","o":["del artículo ochenta y dos de la Constitución.","del artículo ochenta y cuatro de la Constitución.","del artículo ochenta y uno de la Constitución.","del artículo ochenta y seis de la Constitución."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">del artículo ochenta y uno de la Constitución</mark></span>El <span class=\"ref-norma\">art. 28.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"por infracción del artículo ochenta y uno de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7046","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. La admisión de un recurso o de una cuestión de inconstitucionalidad no suspenderá la vigencia ni la aplicación de la Ley, excepto en el caso en que:","o":["la Ley impugnada sea una Ley Orgánica.","el recurrente sea el Defensor del Pueblo.","la Ley impugnada afecte a derechos fundamentales, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento.","el Gobierno se ampare en lo dispuesto por el artículo ciento sesenta y uno, dos, de la Constitución para impugnar, por medio de su Presidente, disposiciones de las Comunidades Autónomas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Gobierno se ampare en lo dispuesto por el artículo ciento sesenta y uno, dos, de la Constitución para impugnar, por medio de su Presidente, disposiciones de las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 30 de LOTC</span> dispone: <span class=\"ref-concepto\">\"excepto en el caso en que el Gobierno se ampare en lo dispuesto por el artículo ciento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7050","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. El recurso de inconstitucionalidad se formulará dentro del plazo de:","o":["dos meses a partir de la publicación de la Ley impugnada.","seis meses a partir de la publicación de la Ley impugnada, conforme al procedimiento que se establezca reglamentariamente.","un mes a partir de la publicación de la Ley impugnada.","tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado</mark></span>El <span class=\"ref-norma\">art. 33.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"se formulará dentro del plazo de tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7051","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. El Presidente del Gobierno y los órganos colegiados ejecutivos de las Comunidades Autónomas podrán interponer el recurso en el plazo de nueve meses cuando, con la finalidad de evitar la interposición del recurso, se cumplan determinados requisitos, entre ellos:","o":["que se reúna la Conferencia de Presidentes.","que se reúna la Comisión General de las Comunidades Autónomas del Senado, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento.","que se reúna la Comisión Bilateral de Cooperación entre la Administración General del Estado y la respectiva Comunidad Autónoma.","que se obtenga un informe del Consejo de Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">que se reúna la Comisión Bilateral de Cooperación entre la Administración General del Estado y la respectiva Comunidad Autónoma</mark></span>El <span class=\"ref-norma\">art. 33.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Que se reúna la Comisión Bilateral de Cooperación entre la Administración General\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7052","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. Uno de los requisitos para el plazo de nueve meses es que el acuerdo de la Comisión Bilateral sea puesto en conocimiento del Tribunal Constitucional dentro de:","o":["los treinta días siguientes a la publicación de la Ley, salvo que el Estado miembro afectado disponga otra cosa.","los tres meses siguientes a la publicación de la Ley, disposición o acto con fuerza de Ley.","los seis meses siguientes a la publicación de la Ley.","los quince días siguientes a la reunión de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los tres meses siguientes a la publicación de la Ley, disposición o acto con fuerza de Ley</mark></span>El <span class=\"ref-norma\">art. 33.2.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"dentro de los tres meses siguientes a la publicación de la\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7054","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Cuando un Juez o Tribunal considere que una norma con rango de Ley aplicable al caso y de cuya validez dependa el fallo pueda ser contraria a la Constitución, podrá plantear la cuestión:","o":["únicamente de oficio.","únicamente a instancia del Ministerio Fiscal.","previa autorización del Consejo General del Poder Judicial.","de oficio o a instancia de parte."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de oficio o a instancia de parte</mark></span>El <span class=\"ref-norma\">art. 35.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"de oficio o a instancia de parte, considere que una\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7059","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El órgano judicial elevará al Tribunal Constitucional la cuestión de inconstitucionalidad junto con:","o":["copia de la sentencia dictada en primera instancia, conforme al procedimiento que se establezca reglamentariamente.","informe del Ministerio Fiscal.","testimonio de los autos principales y de las alegaciones previstas, si las hubiere.","dictamen del Consejo de Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">testimonio de los autos principales y de las alegaciones previstas, si las hubiere</mark></span>El <span class=\"ref-norma\">art. 36 de LOTC</span> dispone: <span class=\"ref-concepto\">\"junto con testimonio de los autos principales y de las alegaciones previstas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7063","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Pleno. Señale la INCORRECTA sobre las competencias del Pleno del Tribunal Constitucional:","o":["Conoce de los conflictos entre los órganos constitucionales del Estado, sin perjuicio de lo dispuesto en el Derecho nacional.","Conoce de la recusación de los Magistrados del Tribunal Constitucional.","Conoce de los recursos de amparo salvo los de mera aplicación de doctrina.","Aprueba y modifica los reglamentos del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Conoce de los recursos de amparo salvo los de mera aplicación de doctrina</mark></span>El <span class=\"ref-norma\">art. 10 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"g) De los conflictos entre los órganos constitucionales del Estado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7064","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Plazo del recurso de inconstitucionalidad. Señale la INCORRECTA sobre el plazo del recurso de inconstitucionalidad:","o":["El plazo general es de tres meses desde la publicación de la norma.","El plazo general es de seis meses desde la publicación de la norma.","El plazo especial es de nueve meses para el Presidente del Gobierno y los órganos ejecutivos autonómicos si se cumplen los requisitos.","Los demás legitimados pueden recurrir en el plazo general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El plazo general es de seis meses desde la publicación de la norma</mark></span>El <span class=\"ref-norma\">art. 33 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"se formulará dentro del plazo de tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7151","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. Las sentencias recaídas en procedimientos de inconstitucionalidad tendrán el valor de cosa juzgada, vincularán a todos los Poderes Públicos y producirán efectos generales:","o":["desde la fecha de su publicación en el «Boletín Oficial del Estado».","desde la fecha de su notificación a las partes.","desde la fecha de su aprobación por el Pleno.","desde la fecha de entrada en vigor de la ley impugnada, en los términos que establezca el propio Reglamento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">desde la fecha de su publicación en el «Boletín Oficial del Estado»</mark></span>El <span class=\"ref-norma\">art. 38.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"producirán efectos generales desde la fecha de su publicación en el «Boletín Oficial del Estado»\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7152","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. Las sentencias desestimatorias dictadas en recursos de inconstitucionalidad y en conflictos en defensa de la autonomía local impedirán cualquier planteamiento ulterior de la cuestión por cualquiera de las dos vías, siempre que esté:","o":["fundado en el mismo recurrente.","fundado en una norma de idéntico rango.","fundado en el mismo plazo de impugnación, salvo que el Estado miembro afectado disponga otra cosa.","fundado en la misma infracción de idéntico precepto constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">fundado en la misma infracción de idéntico precepto constitucional</mark></span>El <span class=\"ref-norma\">art. 38.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"fundado en la misma infracción de idéntico precepto constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7154","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. El Juez o Tribunal quedará vinculado a la sentencia constitucional desde que tuviere conocimiento de ella, y las partes:","o":["desde la fecha de su publicación.","desde el momento en que sean notificadas.","desde que el Tribunal Constitucional la comunique al Ministerio Fiscal.","desde que adquiera firmeza."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">desde el momento en que sean notificadas</mark></span>El <span class=\"ref-norma\">art. 38.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las partes desde el momento en que sean notificadas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7157","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de las sentencias de inconstitucionalidad. Las sentencias declaratorias de la inconstitucionalidad no permitirán revisar procesos fenecidos mediante sentencia con fuerza de cosa juzgada, salvo en el caso de:","o":["los procesos civiles en los que se haya aplicado la norma inconstitucional, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","los procesos laborales en los que se hayan reconocido derechos.","los procesos penales o contencioso-administrativos referentes a un procedimiento sancionador en que, como consecuencia de la nulidad de la norma aplicada, resulte una reducción de la pena o de la sanción o una exclusión, exención o limitación de la responsabilidad.","los procesos penales en los que se haya impuesto una pena de prisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los procesos penales o contencioso-administrativos referentes a un procedimiento sancionador en que, como consecuencia de la nulidad de la norma aplicada, resulte una reducción de la pena o de la sanción o una exclusión, exención o limitación de la responsabilidad</mark></span>El <span class=\"ref-norma\">art. 40.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"salvo en el caso de los procesos penales o contencioso-\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7158","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de las sentencias de inconstitucionalidad. La jurisprudencia de los tribunales de justicia recaída sobre leyes, disposiciones o actos enjuiciados por el Tribunal Constitucional habrá de entenderse:","o":["vinculante para el Tribunal Constitucional.","corregida por la doctrina derivada de las sentencias y autos que resuelvan los procesos constitucionales.","prevalente sobre la doctrina constitucional en materia de legalidad ordinaria, sin perjuicio de lo dispuesto en el Derecho nacional.","suspendida hasta la publicación de la sentencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">corregida por la doctrina derivada de las sentencias y autos que resuelvan los procesos constitucionales</mark></span>El <span class=\"ref-norma\">art. 40.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"habrá de entenderse corregida por la doctrina derivada de las sentencias y autos que resuelvan los procesos constitucionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7163","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. Las violaciones de derechos originadas por actos del Gobierno o de sus autoridades o funcionarios podrán dar lugar al recurso de amparo:","o":["una vez que se haya agotado la vía judicial procedente.","en cualquier momento, sin necesidad de agotar la vía previa.","una vez interpuesto recurso de alzada.","previa solicitud de informe al Defensor del Pueblo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una vez que se haya agotado la vía judicial procedente</mark></span>El <span class=\"ref-norma\">art. 43.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán dar lugar al recurso de amparo una vez que se haya agotado la vía judicial procedente\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7165","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. En el amparo frente a actos del Gobierno, el recurso solo podrá fundarse en:","o":["la infracción de cualquier precepto de la Constitución.","la infracción de una norma de legalidad ordinaria.","la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo.","la infracción de los tratados internacionales sobre derechos humanos, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo</mark></span>El <span class=\"ref-norma\">art. 43.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso sólo podrá fundarse en la infracción por una resolución firme de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7183","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del amparo. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de:","o":["diez días, remita las actuaciones o testimonio de ellas.","cinco días, remita las actuaciones o testimonio de ellas.","quince días, remita las actuaciones o testimonio de ellas.","veinte días, remita las actuaciones o testimonio de ellas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez días, remita las actuaciones o testimonio de ellas</mark></span>El <span class=\"ref-norma\">art. 51.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7184","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del amparo. El órgano, autoridad, Juez o Tribunal acusará inmediato recibo del requerimiento, cumplimentará el envío dentro del plazo señalado y emplazará a quienes fueron parte en el procedimiento antecedente para que puedan comparecer en el proceso constitucional en el plazo de:","o":["cinco días.","quince días.","veinte días.","diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">diez días</mark></span>El <span class=\"ref-norma\">art. 51.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"para que puedan comparecer en el proceso constitucional en el plazo de diez días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7189","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Resolución del amparo. Cuando la Sala conozca del recurso de amparo respecto de decisiones de jueces y tribunales, limitará su función a concretar si se han violado derechos o libertades del demandante y a preservar o restablecer estos derechos, y se abstendrá:","o":["de pronunciarse sobre la imposición de costas.","de conocer de recursos contra resoluciones del Tribunal Supremo, salvo que el Estado miembro afectado disponga otra cosa.","de cualquier otra consideración sobre la actuación de los órganos jurisdiccionales.","de cualquier consideración sobre los hechos probados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de cualquier otra consideración sobre la actuación de los órganos jurisdiccionales</mark></span>El <span class=\"ref-norma\">art. 54 de LOTC</span> dispone: <span class=\"ref-concepto\">\"y se abstendrá de cualquier otra consideración sobre la actuación de los órganos jurisdiccionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7198","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Modificación de la suspensión. La suspensión o su denegación puede ser modificada durante el curso del juicio de amparo constitucional, de oficio o a instancia de parte, en virtud de:","o":["un cambio de doctrina del Tribunal Constitucional.","circunstancias sobrevenidas o que no pudieron ser conocidas al tiempo de sustanciarse el incidente de suspensión.","la presentación de nueva documentación por el recurrente, conforme al procedimiento que se establezca reglamentariamente.","la petición del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">circunstancias sobrevenidas o que no pudieron ser conocidas al tiempo de sustanciarse el incidente de suspensión</mark></span>El <span class=\"ref-norma\">art. 57 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en virtud de circunstancias sobrevenidas o que no pudieron ser conocidas al tiempo de sustanciarse el incidente de suspensión\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7199","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Indemnización por la suspensión. Serán competentes para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión:","o":["los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas.","el propio Tribunal Constitucional, sin perjuicio de lo dispuesto en el Derecho nacional.","el Consejo de Estado.","la Administración demandada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los Jueces o Tribunales, a cuya disposición se pondrán las fianzas constituidas</mark></span>El <span class=\"ref-norma\">art. 58.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Serán competentes para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión los Jueces o Tribunales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7201","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. Señale la INCORRECTA sobre el recurso de amparo frente a violaciones originadas por el Gobierno o sus autoridades:","o":["Exige haber agotado la vía judicial procedente.","El plazo es de veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","Puede interponerse sin necesidad de agotar la vía judicial procedente.","Solo puede fundarse en la infracción de preceptos constitucionales que reconocen derechos susceptibles de amparo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Puede interponerse sin necesidad de agotar la vía judicial procedente</mark></span>El <span class=\"ref-norma\">art. 43 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán dar lugar al recurso de amparo una vez que se haya agotado la vía judicial procedente\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 34 — Tramitación del recurso","q":[{"i":"7-12","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de _______ remita las actuaciones o testimonio de ellas.","o":["Diez días.","Veinte días.","Un mes.","Tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 51.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.\"</span>."},{"i":"7-ia-7053","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del recurso de inconstitucionalidad. Admitida a trámite la demanda, la personación y la formulación de alegaciones deberán hacerse en el plazo de quince días, transcurrido el cual el Tribunal dictará sentencia en el de:","o":["diez días, salvo que, mediante resolución motivada, estime necesario un plazo más amplio que no podrá exceder de treinta días.","quince días, salvo que se solicite una prórroga de un mes, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","treinta días, sin posibilidad de ampliación.","diez días, sin posibilidad de ampliación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez días, salvo que, mediante resolución motivada, estime necesario un plazo más amplio que no podrá exceder de treinta días</mark></span>El <span class=\"ref-norma\">art. 34.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"transcurrido el cual el Tribunal dictará sentencia en el de diez, salvo que\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7062","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El Tribunal Constitucional dará traslado de la cuestión de inconstitucionalidad al Congreso, al Senado, al Fiscal General del Estado y al Gobierno. Concluido el plazo de alegaciones, el Tribunal dictará sentencia en el plazo de:","o":["diez días, salvo que se prorrogue por quince días, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","treinta días, sin posibilidad de ampliación.","quince días, sin posibilidad de ampliación.","quince días, salvo que estime necesario, mediante resolución motivada, un plazo más amplio que no podrá exceder de treinta días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">quince días, salvo que estime necesario, mediante resolución motivada, un plazo más amplio que no podrá exceder de treinta días</mark></span>El <span class=\"ref-norma\">art. 37.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Concluido éste, el Tribunal dictará sentencia en el plazo de quince días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 47 — Comparecencia y Ministerio Fiscal","q":[{"i":"7-13","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Recurso de amparo Constitucional. La Procedencia e Interposición del Recurso de amparo Constitucional. Podrán comparecer en el proceso de amparo Constitucional, con el carácter de demandado o con el de _______ las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.","o":["Demandante.","Coadyuvante.","Interesado.","Todos son correctos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Coadyuvante</mark></span>Demandante e «interesado» no son las figuras que cita el artículo. Según el <span class=\"ref-norma\">art. 47.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Podrán comparecer en el proceso de amparo constitucional, con el carácter de demandado o con el de coadyuvante, las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo\"</span> (verificado con el texto del temario)."},{"i":"7-121","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Podrán comparecer en el proceso de amparo constitucional, con el carácter de ___________, las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.","o":["demandado.","Coadyuvante.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 47.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Podrán comparecer en el proceso de amparo constitucional, con el carácter de demandado o con el de coadyuvante, las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.\"</span>."},{"i":"7-ia-7173","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Comparecencia en el amparo. Podrán comparecer en el proceso de amparo constitucional, con el carácter de demandado o con el de coadyuvante:","o":["únicamente las personas favorecidas por la decisión impugnada, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","las Administraciones Públicas afectadas.","las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo.","cualquier persona física o jurídica."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo</mark></span>El <span class=\"ref-norma\">art. 47.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las personas favorecidas por la decisión, acto o hecho en razón del cual se formule el recurso o que ostenten un interés legítimo en el mismo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7174","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Comparecencia en el amparo. El Ministerio Fiscal intervendrá en todos los procesos de amparo, en defensa de la legalidad, de los derechos de los ciudadanos y:","o":["del orden constitucional.","del interés público tutelado por la Ley.","de la independencia judicial, sin perjuicio de lo dispuesto en el Derecho nacional.","de la seguridad jurídica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del interés público tutelado por la Ley</mark></span>El <span class=\"ref-norma\">art. 47.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la Ley\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · LO 2/1979 del Tribunal Constitucional — R1 a R9","q":[{"i":"7-14","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tribunal Constitucional, su organización y Atribuciones. Sobre la cuestión de jurisdicción o competencia el Tribunal Constitucional: Señale la correcta.","o":["En ningún caso se podrá pronunciar.","El conocimiento no se podrá promover en cuestión de Jurisdicción.","El conocimiento se podrá promover sobre la competencia.","Se podrá pronunciar sobre la competencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se podrá pronunciar sobre la competencia</mark></span>El <span class=\"ref-norma\">art. 4.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"En ningún caso se podrá promover cuestión de jurisdicción o competencia al Tribunal Constitucional. El Tribunal Constitucional delimitará el ámbito de su jurisdicción y adoptará cuantas medidas sean necesarias para preservarla, incluyendo la declaración de nulidad de aquellos actos o resoluciones que la menoscaben; asimismo podrá apreciar de oficio o a instancia de parte su competencia o incompetencia.\"</span>."},{"i":"7-19","p":"Ley Orgánica del Tribunal Constitucional. Recurso de amparo. ¿En qué plazo deberán presentarse las peticiones de indemnización?","o":["En el plazo de tres meses desde que la sentencia devenga firme.","En el plazo de seis meses desde que se notifique la sentencia.","En el plazo de un año a partir de la publicación de la sentencia.","En el plazo de dos años desde que se publique la sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el plazo de un año a partir de la publicación de la sentencia</mark></span>El plazo es de un año desde la PUBLICACIÓN de la sentencia (no desde que sea firme). Según el <span class=\"ref-norma\">art. 58.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las peticiones de indemnización [...] deberán presentarse dentro del plazo de un año a partir de la publicación de la sentencia del Tribunal Constitucional\"</span> (verificado con el texto del temario)."},{"i":"7-66","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué órgano jurisdiccional entenderá de los conflictos en defensa de la autonomía local?","o":["El Tribunal Constitucional.","La Audiencia Provincial.","El Tribunal Superior de Justicia.","El Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 2.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"d) De los conflictos entre los órganos constitucionales del Estado. d) bis. De los conflictos en defensa de la autonomía local. e) De la declaración sobre la constitucionalidad de los tratados internacionales.\"</span>."},{"i":"7-72","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo constitucional. El conocimiento de los recursos de amparo constitucional corresponde a:","o":["Las Salas del Tribunal Constitucional y, en su caso, a las Secciones.","El Pleno, entre otros.","Las Salas del Tribunal Constitucional, exclusivamente.","Las respuestas A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Salas del Tribunal Constitucional y, en su caso, a las Secciones</mark></span>No es «exclusivamente» de las Salas: también las Secciones, en su caso. Según el <span class=\"ref-norma\">art. 48 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El conocimiento de los recursos de amparo constitucional corresponde a las Salas del Tribunal Constitucional y, en su caso, a las Secciones\"</span> (verificado con el texto del temario)."},{"i":"7-104","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué órgano elabora los presupuestos del Tribunal Constitucional?","o":["El Pleno.","La Gran Sala.","La Sala.","La Sección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Pleno</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>."},{"i":"7-145","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. En las violaciones originadas por el Gobierno o sus autoridades o funcionarios, el plazo para interponer el recurso de amparo constitucional será el de los:","o":["Treinta días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","Veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","Veinte días siguientes a la fecha de la resolución recaída en el previo proceso judicial.","Tres meses siguientes a la notificación de la resolución recaída en el previo proceso judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial</mark></span>El <span class=\"ref-norma\">art. 43.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo constitucional será el de los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial.\"</span>. 20 días (Gobierno) · 30 días (órganos judiciales) · 3 meses (actos sin valor de Ley de las Cortes y Asambleas). <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado R5 en tu temario)</em>"},{"i":"7-ia-7012","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Defensa de su jurisdicción. Respecto a la jurisdicción del Tribunal Constitucional, en ningún caso se podrá promover:","o":["recurso de amparo contra sus resoluciones.","cuestión de jurisdicción o competencia al Tribunal Constitucional.","cuestión de inconstitucionalidad contra sus reglamentos, en los términos que establezca el propio Reglamento.","cuestión prejudicial ante el Tribunal Supremo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuestión de jurisdicción o competencia al Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 4.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En ningún caso se podrá promover cuestión de jurisdicción o competencia al Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7016","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Composición. El Tribunal Constitucional está integrado por doce miembros, con el título de:","o":["Vocales del Tribunal Constitucional.","Magistrados del Tribunal Constitucional.","Consejeros del Tribunal Constitucional, sin perjuicio de lo dispuesto en el Derecho nacional.","Jueces del Tribunal Constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Magistrados del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 5 de LOTC</span> dispone: <span class=\"ref-concepto\">\"está integrado por doce miembros, con el título de Magistrados del Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7035","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Distribución de asuntos. La distribución de asuntos entre las Salas del Tribunal se efectuará según un turno establecido por:","o":["el Presidente a propuesta del Pleno.","el Vicepresidente.","el Pleno a propuesta de su Presidente.","el Consejo General del Poder Judicial, salvo que el Estado miembro afectado disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Pleno a propuesta de su Presidente</mark></span>El <span class=\"ref-norma\">art. 12 de LOTC</span> dispone: <span class=\"ref-concepto\">\"según un turno establecido por el Pleno a propuesta de su Presidente\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7047","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Recurso de inconstitucionalidad. El recurso de inconstitucionalidad contra las Leyes, disposiciones normativas o actos con fuerza de Ley podrá promoverse:","o":["a partir de su entrada en vigor.","a partir de su sanción por el Rey.","a partir de su publicación oficial.","a partir de su aprobación por las Cortes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a partir de su publicación oficial</mark></span>El <span class=\"ref-norma\">art. 31 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrá promoverse a partir de su publicación oficial\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7153","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia en procedimientos de inconstitucionalidad y sus efectos. En las sentencias recaídas en cuestiones de inconstitucionalidad, el Tribunal Constitucional lo comunicará inmediatamente al órgano judicial competente para la decisión del proceso. Dicho órgano:","o":["publicará la sentencia en el «Boletín Oficial del Estado».","remitirá la sentencia al Consejo General del Poder Judicial.","notificará la sentencia constitucional a las partes.","dictará sentencia en el plazo de diez días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">notificará la sentencia constitucional a las partes</mark></span>El <span class=\"ref-norma\">art. 38.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Dicho órgano notificará la sentencia constitucional a las partes\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7164","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos del Gobierno. En los casos de violaciones de derechos originadas por el Gobierno o sus autoridades, el plazo para interponer el recurso de amparo será el de:","o":["los treinta días siguientes a la notificación de la resolución recaída en el previo proceso judicial.","los tres meses siguientes a la notificación de la resolución judicial.","los diez días siguientes a la notificación de la resolución judicial.","los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial</mark></span>El <span class=\"ref-norma\">art. 43.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo constitucional será el de los veinte días siguientes a la notificación de la resolución recaída en el previo proceso judicial\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7175","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Tramitación del amparo. El conocimiento de los recursos de amparo constitucional corresponde:","o":["a las Salas del Tribunal Constitucional y, en su caso, a las Secciones.","al Pleno del Tribunal Constitucional.","a las Secciones, con revisión del Pleno, en los términos que establezca el propio Reglamento.","a la Sala Primera exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a las Salas del Tribunal Constitucional y, en su caso, a las Secciones</mark></span>El <span class=\"ref-norma\">art. 48 de LOTC</span> dispone: <span class=\"ref-concepto\">\"corresponde a las Salas del Tribunal Constitucional y, en su caso, a las Secciones\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7200","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Indemnización por la suspensión. Las peticiones de indemnización por la suspensión, que se sustanciarán por el trámite de los incidentes, deberán presentarse dentro del plazo de:","o":["seis meses a partir de la publicación de la sentencia.","tres meses a partir de la notificación de la sentencia, en los términos que establezca el propio Reglamento.","dos años a partir de la publicación de la sentencia.","un año a partir de la publicación de la sentencia del Tribunal Constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un año a partir de la publicación de la sentencia del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 58.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"deberán presentarse dentro del plazo de un año a partir de la publicación de la sentencia del Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"General / Derechos y Deberes Fundamentales (CE)","q":[{"i":"7-17","p":"Ley Orgánica del Tribunal Constitucional. La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de:","o":["Las cuestiones prejudiciales que se le planteen por el orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de esta.","Las cuestiones incidentales de potencias entre el orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de esta.","Las opciones A y B son correctas.","Las opciones A y B son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones A y B son incorrectas</mark></span>Son cuestiones NO pertenecientes al orden constitucional; A y B dicen lo contrario o están alteradas. Según el <span class=\"ref-norma\">art. 3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta\"</span> (verificado con el texto del temario)."},{"i":"7-20","p":"Ley Orgánica del Tribunal Constitucional. Son susceptibles de declaración de inconstitucionalidad entre otros:","o":["Los Tratados internacionales.","Los Reglamentos de las Cámaras y de las Cortes Generales.","Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>Las tres son susceptibles de declaración de inconstitucionalidad. Según el <span class=\"ref-norma\">art. 27.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Son susceptibles de declaración de inconstitucionalidad: [...] c) Los Tratados Internacionales. d) Los Reglamentos de las Cámaras y de las Cortes Generales. [...] f) Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas\"</span> (verificado con el texto del temario)."},{"i":"7-21","p":"Ley Orgánica del Tribunal Constitucional. ¿De qué forma se integran los presupuestos del Tribunal Constitucional en los Presupuestos Generales del Estado?","o":["Se integra como una sección independiente dentro de los Presupuestos Generales del Estado.","Se integra como una sección dependiente dentro de los Presupuestos Generales del Estado.","Se integra de forma genérica en los Presupuestos Generales del Estado.","No se encuentran integrados en los Presupuestos Generales del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se integra como una sección independiente dentro de los Presupuestos Generales del Estado</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>."},{"i":"7-24","p":"Ley Orgánica del Tribunal Constitucional. Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo _______ remita las actuaciones o testimonio de ellas.","o":["que no podrá exceder de diez días.","que no podrá exceder de veinte días.","Entre diez y veinte días.","Entre diez y quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que no podrá exceder de diez días</mark></span>El <span class=\"ref-norma\">art. 51.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Admitida la demanda de amparo, la Sala requerirá con carácter urgente al órgano o a la autoridad de que dimane la decisión, el acto o el hecho, o al Juez o Tribunal que conoció del procedimiento precedente para que, en plazo que no podrá exceder de diez días, remita las actuaciones o testimonio de ellas.\"</span>."},{"i":"7-27","p":"Ley Orgánica del Tribunal Constitucional. ¿Cómo se efectuará la votación para la elección del Presidente del Tribunal Constitucional?","o":["La votación será secreta.","La votación será pública.","La votación será secreta, siendo solo accesos a los Magistrados que participen en la misma.","No existe tal votación, puesto que es elegido por el Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La votación será secreta</mark></span>El <span class=\"ref-norma\">art. 9.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento.\"</span>."},{"i":"7-49","p":"Ley Orgánica del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina: Señale la opción incorrecta.","o":["De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de las de éstas entre sí.","De los conflictos constitucionales en materia electoral.","De la declaración sobre la constitucionalidad de los Tratados Internacionales.","De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De los conflictos constitucionales en materia electoral</mark></span>En el art. 2.1 no figuran los «conflictos constitucionales en materia electoral». Según el <span class=\"ref-norma\">art. 2.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"De la declaración sobre la constitucionalidad de los tratados internacionales\"</span> (verificado con el texto del temario)."},{"i":"7-50","p":"Ley Orgánica del Tribunal Constitucional. ¿Es renovable el mandato del Presidente del Tribunal Constitucional?","o":["No, solo podrá ser elegido una sola vez.","Sí, aunque sólo se podrá re-elegir por una sola vez.","Sí, es renovable hasta que se alcance el límite de edad para ejercer como Magistrado.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sí, aunque sólo se podrá re-elegir por una sola vez.</mark></span> El <span class=\"ref-norma\">art. 9.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El nombre del elegido se elevará al Rey para su nombramiento por un período de tres años, expirado el cual podrá ser reelegido por una sola vez.\"</span> TEST 4"},{"i":"7-89","p":"Ley Orgánica del Tribunal Constitucional. De la tramitación de los recursos de amparo constitucional. En el proceso por recurso de amparo, la Sala, o en su caso la Sección, pronunciará la sentencia que proceda en el plazo de diez días a partir del día señalado para la vista o deliberación.","o":["Diez días.","Tres días.","Cinco días.","Siete días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 52.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sala, o en su caso la Sección, pronunciará la sentencia que proceda en el plazo de 10 días a partir del día señalado para la vista o deliberación.\"</span>."}]},{"a":"Artículo 44 — Amparo frente a órganos judiciales","q":[{"i":"7-25","p":"Ley Orgánica del Tribunal Constitucional. Las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial, podrán dar lugar a este recurso siempre que se cumplan los requisitos siguientes: Señale la opción correcta.","o":["Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquéllas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional.","Que se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial.","Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 44.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquellas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional. c) Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.\"</span>. La opción C original («sin haber denunciado…») invertía el requisito: hay que haber denunciado formalmente la vulneración."}]},{"a":"Artículo 32 — Legitimación","q":[{"i":"7-34","p":"Ley Orgánica del Tribunal Constitucional. Están legitimados para el ejercicio del recurso de inconstitucionalidad cuando se trate de Estatutos de Autonomía y demás Leyes del Estado, orgánicas o en cualesquiera de sus formas, y disposiciones normativas y actos del Estado o de las Comunidades Autónomas con fuerza de ley, Tratados Internacionales y Reglamentos de las Cámaras y de las Cortes Generales:","o":["El Consejo de Ministros.","50 Diputados.","60 Senadores.","80 miembros de las Cortes Generales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">50 Diputados</mark></span>El <span class=\"ref-norma\">art. 32.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"a) El Presidente del Gobierno. b) El Defensor del Pueblo. c) Cincuenta Diputados. d) Cincuenta Senadores.\"</span>."},{"i":"7-95","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De los procedimientos de declaración de inconstitucionalidad. Son susceptibles de declaración de inconstitucionalidad:","o":["Los Estatutos de Autonomía y las demás Leyes orgánicas.","Los Reglamentos de las Cámaras y de las Cortes Generales.","Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 50.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso solamente cuando concurran todos los siguientes requisitos\"</span>."},{"i":"7-ia-7048","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación para el recurso de inconstitucionalidad. Están legitimados para el ejercicio del recurso de inconstitucionalidad contra Estatutos de Autonomía y demás Leyes del Estado:","o":["el Presidente del Gobierno, el Defensor del Pueblo, cuarenta Diputados y cuarenta Senadores.","el Presidente del Gobierno, el Defensor del Pueblo, cincuenta Diputados y cincuenta Senadores.","el Presidente del Gobierno, el Fiscal General del Estado, cincuenta Diputados y cincuenta Senadores.","el Gobierno, el Defensor del Pueblo, cincuenta Diputados y veinticinco Senadores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Presidente del Gobierno, el Defensor del Pueblo, cincuenta Diputados y cincuenta Senadores</mark></span>El <span class=\"ref-norma\">art. 32.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) El Presidente del Gobierno. b) El Defensor del Pueblo. c) Cincuenta Diputados. d) Cincuenta Senadores\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7049","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación para el recurso de inconstitucionalidad. Para el recurso de inconstitucionalidad contra Leyes del Estado que puedan afectar a su propio ámbito de autonomía, están también legitimados:","o":["los órganos colegiados ejecutivos y las Asambleas de las Comunidades Autónomas, previo acuerdo adoptado al efecto.","los Presidentes de las Comunidades Autónomas, sin necesidad de acuerdo, salvo que el Estado miembro afectado disponga otra cosa.","los Parlamentos autonómicos, por mayoría absoluta.","las Comunidades Autónomas a través del Defensor del Pueblo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los órganos colegiados ejecutivos y las Asambleas de las Comunidades Autónomas, previo acuerdo adoptado al efecto</mark></span>El <span class=\"ref-norma\">art. 32.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"están también legitimados los órganos colegiados ejecutivos y las Asambleas de las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · LO 1/1982 honor, intimidad e imagen — R10 a R13","q":[{"i":"7-35","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Señale la opción incorrecta.","o":["La existencia de prejuicio no se presumirá aunque se acredite la intromisión ilegítima.","Tendrá la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 7 de esta ley, la utilización del delito por el condenado en sentencia penal firme para conseguir notoriedad pública u obtener provecho económico, o la divulgación de datos falsos sobre los hechos delictivos, cuando ello suponga el menoscabo de la dignidad de las víctimas.","El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, garantizado en el artículo 18 de la Constitución, será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en esta Ley Orgánica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La existencia de prejuicio no se presumirá aunque se acredite la intromisión ilegítima</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La existencia de perjuicio se presumirá siempre que se acredite la intromisión ilegítima.\"</span>. La ley dice que el perjuicio se PRESUME siempre que se acredite la intromisión."},{"i":"7-48","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Señale la opción incorrecta.","o":["El consentimiento otorgado para la intromisión ilegítima será revocable en cualquier momento, sin que proceda indemnización alguna por las acciones realizadas hasta ese momento.","El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, garantizado en el artículo 18 de la Constitución, será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en esta Ley Orgánica.","El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","Tendrá la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 7 de esta Ley, el emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El consentimiento otorgado para la intromisión ilegítima será revocable en cualquier momento, sin que proceda indemnización alguna por las acciones realizadas hasta ese momento</mark></span>El <span class=\"ref-norma\">art. 2.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento a que se refiere el párrafo anterior será revocable en cualquier momento, pero habrán de indemnizarse en su caso, los daños y perjuicios causados, incluyendo en ellos las expectativas justificadas.\"</span>. El consentimiento es revocable en cualquier momento, pero con indemnización de los daños y perjuicios causados (incluidas las expectativas justificadas)."},{"i":"7-79","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Disposiciones generales. El consentimiento de los menores e incapaces debe prestarse:","o":["En todo caso, por quienes ejerzan la patria potestad de forma oral o escrita.","Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","En todo caso, mediante escrito por su representante legal.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.\"</span>."},{"i":"7-103","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Disposiciones generales. Señale la INCORRECTA.","o":["El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible.","El consentimiento de los menores e incapaces deberá prestarse por el juez competente, aunque su grado de madurez lo permita, de acuerdo con la legislación civil.","El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien esta haya designado a tal efecto en su testamento. La designación puede recaer en una persona jurídica.","El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El consentimiento de los menores e incapaces deberá prestarse por el juez competente, aunque su grado de madurez lo permita, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.\"</span>."},{"i":"7-137","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Disposiciones generales. El consentimiento de los menores e incapaces deberá prestarse:","o":["En todo caso, por quienes ejerzan la patria potestad o la tutela por escrito.","Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","En todo caso, mediante escrito por su representante legal.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.\"</span>. La regla general es que los menores e incapaces con madurez suficiente consienten por sí mismos; el escrito del representante legal es para los restantes casos."},{"i":"7-ia-7303","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Los derechos garantizados por la Ley han sido encuadrados por la doctrina jurídica entre los derechos de la personalidad, calificación de la que se desprende su carácter:","o":["renunciable.","transmisible.","irrenunciable.","prescriptible, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">irrenunciable</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"entre los derechos de la personalidad, calificación de la que obviamente se desprende el carácter de irrenunciable\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7315","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Consentimiento de menores e incapaces. El consentimiento de los menores e incapaces deberá prestarse por ellos mismos:","o":["en todo caso, con asistencia de sus representantes.","únicamente si han cumplido catorce años.","si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil.","únicamente mediante escrito autorizado por el Ministerio Fiscal, salvo que el Estado miembro afectado disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil</mark></span>El <span class=\"ref-norma\">art. 3.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7343","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones transitorias. En tanto no sean desarrolladas las previsiones constitucionales sobre un procedimiento basado en los principios de preferencia y sumariedad, la tutela judicial de estos derechos se podrá recabar por cualquiera de los procedimientos establecidos en las Secciones II y III de la Ley:","o":["2/1979, de 3 de octubre, del Tribunal Constitucional.","1/2000, de 7 de enero, de Enjuiciamiento Civil.","62/1978, de 26 de diciembre, de Protección Jurisdiccional de los derechos fundamentales de la persona.","29/1998, de 13 de julio, reguladora de la jurisdicción contencioso-administrativa, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">62/1978, de 26 de diciembre, de Protección Jurisdiccional de los derechos fundamentales de la persona</mark></span>El <span class=\"ref-norma\">disp. transitoria segunda de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"por cualquiera de los procedimientos establecidos en las Secciones II y III de la Ley sesenta y dos/mil novecientos setenta y ocho\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 39 — Nulidad","q":[{"i":"7-37","p":"Ley Orgánica del Tribunal Constitucional. Cuando la sentencia declare la inconstitucionalidad:","o":["Declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.","Declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Reglamentos a los que deba extenderse por conexión o consecuencia.","Declarará igualmente la insalvabilidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia</mark></span>El <span class=\"ref-norma\">art. 39.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Cuando la sentencia declare la inconstitucionalidad, declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.\"</span>."},{"i":"7-ia-7155","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de la declaración de inconstitucionalidad. Cuando la sentencia declare la inconstitucionalidad, declarará igualmente la nulidad de los preceptos impugnados, así como, en su caso:","o":["la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia.","la de las disposiciones reglamentarias que los desarrollen, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","la de las resoluciones judiciales que los hayan aplicado.","la de toda la ley en la que se integren."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o consecuencia</mark></span>El <span class=\"ref-norma\">art. 39.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"así como, en su caso, la de aquellos otros de la misma Ley, disposición o acto con fuerza de Ley a los que deba extenderse por conexión o\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7156","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Efectos de la declaración de inconstitucionalidad. El Tribunal Constitucional podrá fundar la declaración de inconstitucionalidad en la infracción de cualquier precepto constitucional:","o":["únicamente si ha sido invocado en el proceso.","únicamente si lo solicita el Ministerio Fiscal.","únicamente si se refiere a derechos fundamentales.","haya o no sido invocado en el curso del proceso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">haya o no sido invocado en el curso del proceso</mark></span>El <span class=\"ref-norma\">art. 39.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"haya o no sido invocado en el curso del\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 29 — Vías de la declaración","q":[{"i":"7-39","p":"Ley Orgánica del Tribunal Constitucional. La declaración de inconstitucionalidad podrá promoverse mediante:","o":["Acción de impugnación directa.","Recurso de inconstitucionalidad promovida por Jueces o Tribunales.","La cuestión de inconstitucionalidad promovida por Jueces o Tribunales.","La cuestión de inconstitucionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La cuestión de inconstitucionalidad promovida por Jueces o Tribunales</mark></span>El <span class=\"ref-norma\">art. 29.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La declaración de inconstitucionalidad podrá promoverse mediante: a) El recurso de inconstitucionalidad. b) La cuestión de inconstitucionalidad promovida por Jueces o Tribunales.\"</span>."},{"i":"7-ia-7044","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. La declaración de inconstitucionalidad podrá promoverse mediante:","o":["el recurso de amparo y la cuestión de inconstitucionalidad.","el recurso de inconstitucionalidad y la cuestión de inconstitucionalidad promovida por Jueces o Tribunales.","el recurso de inconstitucionalidad y el conflicto de competencia, en los términos que establezca el propio Reglamento.","la cuestión de inconstitucionalidad y el recurso previo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el recurso de inconstitucionalidad y la cuestión de inconstitucionalidad promovida por Jueces o Tribunales</mark></span>El <span class=\"ref-norma\">art. 29.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) El recurso de inconstitucionalidad. b) La cuestión de inconstitucionalidad promovida por Jueces o Tribunales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7045","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedimientos de inconstitucionalidad. La desestimación, por razones de forma, de un recurso de inconstitucionalidad contra una Ley no será obstáculo para que la misma Ley pueda ser objeto:","o":["de una cuestión de inconstitucionalidad con ocasión de su aplicación en otro proceso.","de un nuevo recurso de inconstitucionalidad en el mismo año, salvo que el Estado miembro afectado disponga otra cosa.","de un recurso de amparo.","de un conflicto en defensa de la autonomía local."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de una cuestión de inconstitucionalidad con ocasión de su aplicación en otro proceso</mark></span>El <span class=\"ref-norma\">art. 29.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"puedan ser objeto de una cuestión de inconstitucionalidad con ocasión de su aplicación en otro proceso\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 56 — Suspensión y medidas cautelares ✱ R8","q":[{"i":"7-42","p":"Ley Orgánica del Tribunal Constitucional. La interposición del recurso de amparo:","o":["Suspenderá los efectos del acto o sentencia impugnados.","No suspenderá los efectos del acto o sentencia impugnados.","No obstante, cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala, o la Sección en el supuesto del artículo 52.2, de oficio o a instancia del recurrente, podrá disponer la suspensión, total o parcial, de sus efectos, siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona.","Las opciones A y B son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No obstante, cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala, o la Sección en el supuesto del artículo 52.2, de oficio o a instancia del recurrente, podrá disponer la suspensión, total o parcial, de sus efectos, siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona</mark></span>El <span class=\"ref-norma\">art. 56.1 y 2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"1. La interposición del recurso de amparo no suspenderá los efectos del acto o sentencia impugnados. 2. Ello no obstante, cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala, o la Sección en el supuesto del artículo 52.2, de oficio o a instancia del recurrente, podrá disponer la suspensión, total o parcial, de sus efectos, siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona.\"</span>. La regla general es que el recurso NO suspende los efectos; la suspensión es excepcional (art. 56.2)."},{"i":"7-109","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Recurso de amparo. ¿En qué supuestos se podrá adoptar la suspensión y las medidas cautelares y provisionales en la resolución de la admisión a trámite?","o":["En los supuestos de perturbación grave de los derechos del interesado.","En los supuestos de urgencia excepcional.","En los supuestos en que se satisfaga o aporte fianza.","En el supuesto en que se obtenga la oportuna fianza."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En los supuestos de urgencia excepcional</mark></span>Según el <span class=\"ref-norma\">art. 56.6 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"En supuestos de urgencia excepcional, la adopción de la suspensión y de las medidas cautelares y provisionales podrá efectuarse en la resolución de la admisión a trámite\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7192","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. La interposición del recurso de amparo:","o":["suspenderá los efectos del acto o sentencia impugnados.","suspenderá los efectos solo si lo solicita el recurrente, en los términos que establezca el propio Reglamento.","suspenderá los efectos hasta la admisión a trámite.","no suspenderá los efectos del acto o sentencia impugnados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no suspenderá los efectos del acto o sentencia impugnados</mark></span>El <span class=\"ref-norma\">art. 56.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La interposición del recurso de amparo no suspenderá los efectos del acto o sentencia impugnados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7193","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. Cuando la ejecución del acto o sentencia impugnados produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la Sala podrá disponer la suspensión, siempre y cuando:","o":["el recurrente preste caución suficiente.","el Ministerio Fiscal informe favorablemente.","la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona.","el acto impugnado no afecte a una Administración Pública, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona</mark></span>El <span class=\"ref-norma\">art. 56.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"siempre y cuando la suspensión no ocasione perturbación grave a un interés constitucionalmente protegido\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7194","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. El incidente de suspensión se sustanciará con audiencia de las partes y del Ministerio Fiscal, por un plazo común que no excederá de:","o":["cinco días.","tres días.","diez días.","quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres días</mark></span>El <span class=\"ref-norma\">art. 56.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"por un plazo común que no excederá de tres días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7195","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. La suspensión u otra medida cautelar en el amparo podrá pedirse:","o":["en cualquier tiempo, antes de haberse pronunciado la sentencia o decidirse el amparo de otro modo.","únicamente en la demanda de amparo.","únicamente tras la admisión a trámite.","únicamente en el plazo de diez días desde la admisión, sin perjuicio de lo dispuesto en el Derecho nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en cualquier tiempo, antes de haberse pronunciado la sentencia o decidirse el amparo de otro modo</mark></span>El <span class=\"ref-norma\">art. 56.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La suspensión u otra medida cautelar podrá pedirse en cualquier tiempo, antes de haberse pronunciado la sentencia\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7196","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. La Sala o la Sección podrá condicionar la suspensión de la ejecución y la adopción de las medidas cautelares a la satisfacción por el interesado de:","o":["una declaración jurada de responsabilidad.","el informe favorable del Ministerio Fiscal.","la prestación de aval bancario por el importe del acto, en los términos que establezca el propio Reglamento.","la oportuna fianza suficiente para responder de los daños y perjuicios que pudieren originarse."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la oportuna fianza suficiente para responder de los daños y perjuicios que pudieren originarse</mark></span>El <span class=\"ref-norma\">art. 56.5 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a la satisfacción por el interesado de la oportuna fianza suficiente para responder de los daños y perjuicios que pudieren originarse\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7197","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Suspensión de la ejecución. En supuestos de urgencia excepcional, la adopción de la suspensión y de las medidas cautelares podrá efectuarse en la resolución de la admisión a trámite. Dicha adopción podrá ser impugnada en el plazo de:","o":["tres días desde su notificación, por el recurrente.","diez días desde su notificación, por el Ministerio Fiscal, salvo que el Estado miembro afectado disponga otra cosa.","cinco días desde su notificación, por el Ministerio Fiscal y demás partes personadas.","quince días desde su notificación, por las partes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cinco días desde su notificación, por el Ministerio Fiscal y demás partes personadas</mark></span>El <span class=\"ref-norma\">art. 56.6 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrá ser impugnada en el plazo de cinco días desde su notificación, por el Ministerio Fiscal y demás partes personadas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 8 — Las Secciones","q":[{"i":"7-51","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. En caso de que se admita una causa por el Tribunal Constitucional, ¿quién podrá asumir el conocimiento del asunto de que se trate?","o":["El Pleno.","El Pleno, aunque podrá deferir a una Sala.","El Pleno, aunque podrá deferir a una Sala, y ésta a su vez en una Sección.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Pleno, aunque podrá deferir a una Sala</mark></span>El <span class=\"ref-norma\">art. 8.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"En el caso de admisión, el Pleno podrá deferir a la Sala que corresponda el conocimiento del asunto de que se trate, en los términos previstos en esta ley.\"</span>."},{"i":"7-101","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué asuntos podrán asumir las Secciones en cuanto a su conocimiento y resolución?","o":["Las cuestiones de inconstitucionalidad.","Los asuntos de amparo.","Los conflictos de competencia.","Las impugnaciones previstas en la Constitución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los asuntos de amparo</mark></span>Según el <span class=\"ref-norma\">art. 8.3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Podrá corresponder también a las Secciones el conocimiento y resolución de aquellos asuntos de amparo que la Sala correspondiente les defiera\"</span> (verificado con el texto del temario)."},{"i":"7-138","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Para el despacho ordinario y la decisión o propuesta, según proceda, sobre la admisibilidad o inadmisibilidad de procesos constitucionales, el Pleno y las Salas constituirán Secciones compuestas por:","o":["El Presidente y un Magistrado.","El Presidente o quien le sustituya y dos Magistrados.","El Presidente, el Vicepresidente y un Magistrado.","El Presidente, el Vicepresidente y dos Magistrados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Presidente o quien le sustituya y dos Magistrados</mark></span>El <span class=\"ref-norma\">art. 8.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"el Pleno y las Salas constituirán Secciones compuestas por el respectivo Presidente o quien le sustituya y dos Magistrados.\"</span>."},{"i":"7-ia-7022","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Secciones. Para el despacho ordinario y la decisión o propuesta sobre la admisibilidad o inadmisibilidad de procesos constitucionales, el Pleno y las Salas constituirán Secciones compuestas por el respectivo Presidente o quien le sustituya y:","o":["tres Magistrados.","un Magistrado.","cuatro Magistrados.","dos Magistrados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos Magistrados</mark></span>El <span class=\"ref-norma\">art. 8.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Secciones compuestas por el respectivo Presidente o quien le sustituya y dos Magistrados\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7023","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Secciones. Se dará cuenta al Pleno de las propuestas de admisión o inadmisión de asuntos de su competencia. En el caso de admisión, el Pleno podrá:","o":["deferir a las Secciones el conocimiento del asunto.","remitir el asunto al Consejo General del Poder Judicial, conforme al procedimiento que se establezca reglamentariamente.","deferir a la Sala que corresponda el conocimiento del asunto de que se trate.","someter el asunto a informe del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">deferir a la Sala que corresponda el conocimiento del asunto de que se trate</mark></span>El <span class=\"ref-norma\">art. 8.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"el Pleno podrá deferir a la Sala que corresponda el\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 41 — Derechos amparables","q":[{"i":"7-57","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Qué protección se le otorga a la objeción de conciencia reconocida en el artículo 30 de la Constitución?","o":["Son susceptibles de cuestión de constitucionalidad.","Son susceptibles de revisión constitucional.","Son susceptibles de amparo constitucional.","Son susceptibles de recurso de constitucionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Son susceptibles de amparo constitucional</mark></span>El <span class=\"ref-norma\">art. 41.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Los derechos y libertades reconocidos en los artículos catorce a veintinueve de la Constitución serán susceptibles de amparo constitucional, en los casos y formas que esta Ley establece, sin perjuicio de su tutela general encomendada a los Tribunales de Justicia. Igual protección será aplicable a la objeción de conciencia reconocida en el artículo treinta de la Constitución.\"</span>."},{"i":"7-122","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Los derechos y libertades reconocidos en los artículos 14 a 29 de la Constitución serán susceptibles de ____________, en los casos y formas que esta ley establece, sin perjuicio de su tutela general encomendada a los Tribunales de Justicia. Igual protección será aplicable a la objeción de conciencia reconocida en el artículo 530 de la Constitución.","o":["de amparo constitucional.","de amparo común.","de protección estatal.","de recurso judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de amparo constitucional</mark></span>El <span class=\"ref-norma\">art. 41.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Los derechos y libertades reconocidos en los artículos catorce a veintinueve de la Constitución serán susceptibles de amparo constitucional, en los casos y formas que esta Ley establece, sin perjuicio de su tutela general encomendada a los Tribunales de Justicia. Igual protección será aplicable a la objeción de conciencia reconocida en el artículo treinta de la Constitución.\"</span>."},{"i":"7-ia-7159","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedencia del recurso de amparo. Los derechos y libertades reconocidos en los artículos catorce a veintinueve de la Constitución serán susceptibles de amparo constitucional, y la misma protección será aplicable a:","o":["la objeción de conciencia reconocida en el artículo treinta de la Constitución.","el derecho de propiedad reconocido en el artículo treinta y tres de la Constitución.","el derecho al trabajo reconocido en el artículo treinta y cinco de la Constitución.","la libertad de empresa reconocida en el artículo treinta y ocho de la Constitución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la objeción de conciencia reconocida en el artículo treinta de la Constitución</mark></span>El <span class=\"ref-norma\">art. 41.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Igual protección será aplicable a la objeción de conciencia reconocida en el artículo treinta de la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7160","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedencia del recurso de amparo. El recurso de amparo constitucional protege frente a las violaciones de los derechos y libertades originadas por disposiciones, actos jurídicos, omisiones o simple vía de hecho de los poderes públicos del Estado, las Comunidades Autónomas y demás entes públicos de carácter territorial, corporativo o institucional, así como:","o":["de las personas privadas que gestionen servicios públicos.","de los partidos políticos y sindicatos.","de las empresas concesionarias de servicios.","de sus funcionarios o agentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de sus funcionarios o agentes</mark></span>El <span class=\"ref-norma\">art. 41.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"así como de sus funcionarios o agentes\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 52 — Vista y sentencia","q":[{"i":"7-77","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo. Recibidas las actuaciones y transcurrido el tiempo de emplazamiento: señale la INCORRECTA.","o":["La Sala dará vista de las mismas a quien promovió el amparo.","La vista será por plazo común que no pueda exceder de veinte días.","La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional.","Durante el plazo establecido podrán presentarse los alegaciones procedentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 52.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala dará vista de las mismas a quien promovió el amparo, a los personados en el proceso, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal. La vista será por plazo común que no podrá exceder de veinte días, y durante él podrán presentarse las alegaciones procedentes.\"</span>."},{"i":"7-127","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Cuándo podrá la Sala deferir la resolución de un recurso de amparo a favor de una de sus Secciones?","o":["Cuando el asunto no goce de una especial trascendencia, a tenor de su importancia para la interpretación de la Constitución.","Cuando su resolución no revista especial complejidad a la vista de lo solicitado y los derechos implicados.","Cuando dicha Sección haya resuelto con anterioridad un recurso con identidad sustantiva.","Cuando para su resolución sea aplicable la doctrina consolidada del Tribunal Constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando para su resolución sea aplicable la doctrina consolidada del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 52.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala podrá deferir la resolución del recurso, cuando para su resolución sea aplicable doctrina consolidada del Tribunal Constitucional, a una de sus Secciones\"</span>."},{"i":"7-131","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo. Recibidas las actuaciones y transcurrido el tiempo de emplazamiento: señale la INCORRECTA.","o":["La Sala dará vista de las mismas a quien promovió el amparo.","La vista será por plazo común que no podrá exceder de veinte días.","La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional.","Durante el plazo establecido podrán presentarse las alegaciones procedentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala dará vista de las mismas en todos los casos al Tribunal Constitucional</mark></span>La vista no se da al Tribunal Constitucional: es la opción falsa. Según el <span class=\"ref-norma\">art. 52.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"la Sala dará vista de las mismas a quien promovió el amparo, a los personados en el proceso, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7185","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Vista en el amparo. Recibidas las actuaciones y transcurrido el tiempo de emplazamiento, la Sala dará vista de las mismas a quien promovió el amparo, a los personados, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal, por plazo común que no podrá exceder de:","o":["diez días.","quince días.","veinte días.","treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">veinte días</mark></span>El <span class=\"ref-norma\">art. 52.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La vista será por plazo común que no podrá exceder de veinte días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7187","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Vista en el amparo. La Sala, o en su caso la Sección, pronunciará la sentencia que proceda en el plazo de:","o":["10 días a partir del día señalado para la vista o deliberación.","15 días a partir del día señalado para la vista o deliberación, en los términos que establezca el propio Reglamento.","20 días a partir del día señalado para la vista o deliberación.","30 días a partir del día señalado para la vista o deliberación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">10 días a partir del día señalado para la vista o deliberación</mark></span>El <span class=\"ref-norma\">art. 52.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"pronunciará la sentencia que proceda en el plazo de 10 días a partir del día señalado para la vista o deliberación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 1 — Naturaleza del Tribunal","q":[{"i":"7-120","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. El Tribunal Constitucional, como _______ de la Constitución, es independiente de los demás órganos constitucionales.","o":["intérprete preferido.","intérprete supremo.","intérprete absoluto.","intérprete constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">intérprete supremo</mark></span>Según el <span class=\"ref-norma\">art. 1.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Tribunal Constitucional, como intérprete supremo de la Constitución, es independiente de los demás órganos constitucionales y está sometido sólo a la Constitución y a la presente Ley Orgánica\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7001","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional, como intérprete supremo de la Constitución, es independiente de los demás órganos constitucionales y está sometido sólo:","o":["a la Constitución y a la presente Ley Orgánica.","a la Constitución y a las demás Leyes Orgánicas que lo regulen.","a la Constitución, a la Ley Orgánica y a la jurisprudencia del Tribunal Supremo.","a la Constitución y a los tratados internacionales ratificados por España."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Constitución y a la presente Ley Orgánica</mark></span>El <span class=\"ref-norma\">art. 1.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"es independiente de los demás órganos constitucionales y está sometido sólo a la Constitución y a la presente Ley Orgánica\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7002","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional es único en su orden y extiende su jurisdicción:","o":["a todo el territorio nacional y a los territorios de ultramar.","a las Comunidades Autónomas que no tengan Tribunal Superior.","a todo el territorio de la Unión Europea.","a todo el territorio nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a todo el territorio nacional</mark></span>El <span class=\"ref-norma\">art. 1.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Es único en su orden y extiende su jurisdicción a todo el territorio nacional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 35 — Planteamiento de la cuestión","q":[{"i":"7-ia-7055","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Antes de adoptar mediante auto su decisión definitiva sobre el planteamiento de la cuestión de inconstitucionalidad, el órgano judicial oirá a las partes y al Ministerio Fiscal para que en el plazo común e improrrogable de:","o":["15 días puedan alegar lo que deseen, en los términos que establezca el propio Reglamento.","5 días puedan alegar lo que deseen.","10 días puedan alegar lo que deseen.","30 días puedan alegar lo que deseen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">10 días puedan alegar lo que deseen</mark></span>El <span class=\"ref-norma\">art. 35.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"en el plazo común e improrrogable de 10 días puedan alegar lo que deseen\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7056","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Oídas las partes y el Ministerio Fiscal, el juez resolverá sobre el planteamiento de la cuestión de inconstitucionalidad en el plazo de:","o":["cinco días.","tres días.","diez días.","quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres días</mark></span>El <span class=\"ref-norma\">art. 35.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"seguidamente y sin más trámite, el juez resolverá en el plazo de tres días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7057","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El auto por el que el juez decide plantear la cuestión de inconstitucionalidad:","o":["no será susceptible de recurso de ninguna clase, aunque la cuestión podrá ser intentada de nuevo en las sucesivas instancias o grados mientras no se llegue a sentencia firme.","será recurrible en apelación ante el órgano superior, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","será recurrible en reposición únicamente.","solo será recurrible ante el Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no será susceptible de recurso de ninguna clase, aunque la cuestión podrá ser intentada de nuevo en las sucesivas instancias o grados mientras no se llegue a sentencia firme</mark></span>El <span class=\"ref-norma\">art. 35.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Dicho auto no será susceptible de recurso de ninguna clase\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7058","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El planteamiento de la cuestión de inconstitucionalidad originará la suspensión provisional de las actuaciones en el proceso judicial hasta que el Tribunal Constitucional se pronuncie sobre su admisión. Producida ésta:","o":["el proceso judicial continuará su tramitación.","el proceso quedará archivado.","el proceso continuará, salvo en la fase de sentencia, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","el proceso judicial permanecerá suspendido hasta que el Tribunal Constitucional resuelva definitivamente sobre la cuestión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el proceso judicial permanecerá suspendido hasta que el Tribunal Constitucional resuelva definitivamente sobre la cuestión</mark></span>El <span class=\"ref-norma\">art. 35.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Producida ésta el proceso judicial permanecerá suspendido\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7065","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Señale la INCORRECTA sobre la cuestión de inconstitucionalidad:","o":["Puede plantearse en cualquier momento del procedimiento, incluso antes de que concluya la fase de prueba.","El órgano judicial oirá a las partes y al Ministerio Fiscal antes de decidir, en los términos que establezca el propio Reglamento.","Origina la suspensión provisional de las actuaciones en el proceso judicial.","El juez resuelve en tres días tras oír a las partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Puede plantearse en cualquier momento del procedimiento, incluso antes de que concluya la fase de prueba</mark></span>El <span class=\"ref-norma\">art. 35 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"El órgano judicial sólo podrá plantear la cuestión una vez concluso el procedimiento y dentro del plazo para dictar sentencia\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 37 — Tramitación ante el Tribunal Constitucional","q":[{"i":"7-ia-7060","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. El Tribunal podrá rechazar, en trámite de admisión, mediante auto y sin otra audiencia que la del Fiscal General del Estado, la cuestión de inconstitucionalidad cuando:","o":["la norma impugnada sea anterior a la Constitución.","faltaren las condiciones procesales o fuere notoriamente infundada la cuestión suscitada.","la cuestión sea planteada por un órgano unipersonal, sin perjuicio de lo dispuesto en el Derecho nacional.","la norma impugnada haya sido derogada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">faltaren las condiciones procesales o fuere notoriamente infundada la cuestión suscitada</mark></span>El <span class=\"ref-norma\">art. 37.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"cuando faltaren las condiciones procesales o fuere notoriamente infundada la cuestión suscitada\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7061","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestión de inconstitucionalidad. Publicada en el «Boletín Oficial del Estado» la admisión a trámite de la cuestión, quienes sean parte en el procedimiento judicial podrán personarse ante el Tribunal Constitucional dentro de:","o":["los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 15 días.","los 10 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 10 días, en los términos que establezca el propio Reglamento.","los 30 días siguientes a su publicación.","los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 10 días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 15 días</mark></span>El <span class=\"ref-norma\">art. 37.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán personarse ante el Tribunal Constitucional dentro de los 15 días siguientes a su publicación, para formular alegaciones, en el plazo de otros 15 días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la","q":[{"i":"7-ia-7301","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo de la Ley, los derechos al honor, a la intimidad personal y familiar y a la propia imagen tienen el rango de fundamentales conforme al precepto constitucional que, además, dispone que el respeto de tales derechos constituya:","o":["un límite al ejercicio de las libertades de expresión.","un límite al ejercicio del derecho de reunión.","un límite al ejercicio de la libertad ideológica.","un límite al derecho de información veraz exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un límite al ejercicio de las libertades de expresión</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"dispone que el respeto de tales derechos constituya un límite al ejercicio de las libertades de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7302","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo, en los casos en que exista protección penal de estos derechos:","o":["tendrá preferente aplicación la protección civil.","se aplicarán ambas protecciones de forma acumulativa, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","se aplicará la protección que elija el perjudicado.","tendrá ésta preferente aplicación, si bien la responsabilidad civil derivada del delito se deberá fijar de acuerdo con los criterios que esta ley establece."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tendrá ésta preferente aplicación, si bien la responsabilidad civil derivada del delito se deberá fijar de acuerdo con los criterios que esta ley establece</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Por ello en los casos que exista la protección penal tendrá ésta preferente aplicación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7304","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Respecto del consentimiento en la intromisión, el preámbulo señala que la ley exige que sea expreso y que, dada la índole particular de estos derechos, permite:","o":["que pueda ser revocado en el plazo de un año sin indemnización, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento.","que pueda ser revocado en cualquier momento, aunque con indemnización de los perjuicios que de la revocación se siguieren al destinatario del mismo.","que sea irrevocable una vez prestado.","que pueda ser tácito cuando sea habitual."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">que pueda ser revocado en cualquier momento, aunque con indemnización de los perjuicios que de la revocación se siguieren al destinatario del mismo</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"permite que pueda ser revocado en cualquier momento, aunque con indemnización de los perjuicios que de la revocación se siguieren al destinatario del mismo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7321","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Pluralidad de legitimados. Cuando sobrevivan varios parientes de los legitimados, cualquiera de ellos podrá ejercer:","o":["las acciones previstas para la protección de los derechos del fallecido.","las acciones únicamente si actúan todos conjuntamente.","las acciones únicamente si lo autoriza el Ministerio Fiscal, conforme al procedimiento que se establezca reglamentariamente.","las acciones únicamente el pariente de mayor edad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las acciones previstas para la protección de los derechos del fallecido</mark></span>El <span class=\"ref-norma\">art. 5.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cualquiera de ellos podrá ejercer las acciones previstas para la protección de los derechos\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7322","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Lesión antes del fallecimiento. Cuando el titular del derecho lesionado fallezca sin haber podido ejercitar por sí o por su representante legal las acciones por las circunstancias en que la lesión se produjo, las acciones podrán ejercitarse:","o":["únicamente por el Ministerio Fiscal, sin perjuicio de lo dispuesto en el Derecho nacional.","únicamente por los herederos.","únicamente por el cónyuge.","por las personas señaladas en el artículo cuarto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por las personas señaladas en el artículo cuarto</mark></span>El <span class=\"ref-norma\">art. 6.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"las referidas acciones podrán ejercitarse por las personas señaladas en el\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7323","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Lesión antes del fallecimiento. Las personas legitimadas podrán continuar la acción ya entablada por el titular del derecho lesionado:","o":["cuando renunciare.","cuando lo autorice el juez.","cuando falleciere.","cuando transcurran cuatro años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuando falleciere</mark></span>El <span class=\"ref-norma\">art. 6.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"podrán continuar la acción ya entablada por el titular del derecho lesionado cuando falleciere\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7342","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposición derogatoria. Según la disposición derogatoria de la Ley, quedan derogadas:","o":["todas las disposiciones anteriores que regulen el honor.","las disposiciones de rango inferior a la ley que regulen la intimidad, salvo que el Estado miembro afectado disponga otra cosa.","las disposiciones del Código Civil contrarias a la presente ley.","cuantas disposiciones de igual o inferior rango se opongan a lo previsto en la presente Ley Orgánica."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuantas disposiciones de igual o inferior rango se opongan a lo previsto en la presente Ley Orgánica</mark></span>El <span class=\"ref-norma\">disp. derogatoria de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Quedan derogadas cuantas disposiciones de igual o inferior rango se opongan a lo previsto en la presente Ley Orgánica\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
